          </div>
          <DialogFooter><Button variant="ghost" onClick={() => setShowAdd(false)}>Cancel</Button><Button onClick={create} data-testid="confirm-add-wh">Add</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </CardContent></Card>
  );
}

