import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import { Snowflake, Plus, Loader2, Trash2, Pencil, Calendar, Shield, RefreshCw, GitBranch, Check, ChevronsUpDown } from "lucide-react";
import { toast } from "sonner";
import HeroTile from "@/components/HeroTile";
import OperationalPageHeader from "@/components/OperationalPageHeader";

const KIND_OPTIONS = [
  { v: "patch", label: "Patches" },
  { v: "reboot", label: "Reboots" },
  { v: "script", label: "Scripts" },
  { v: "broadcast", label: "Broadcasts" },
  { v: "deploy", label: "Deployments" },
];

function useApi(token) {
  return useMemo(() => ({
    get: (p) => axios.get(`${API}${p}`, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data),
    post: (p, b) => axios.post(`${API}${p}`, b || {}, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data),
    put: (p, b) => axios.put(`${API}${p}`, b || {}, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data),
    del: (p) => axios.delete(`${API}${p}`, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.data),
  }), [token]);
}

export default function ChangeFreezePage() {
  const { token } = useAuth();
  const navigate = useNavigate();
  const api = useApi(token);
  const [freezes, setFreezes] = useState([]);
  const [activeOnly, setActiveOnly] = useState(false);
  const [loading, setLoading] = useState(true);
  const [clients, setClients] = useState([]);
  const [editorOpen, setEditorOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);

  const reload = () => {
    setLoading(true);
    api.get("/change-freezes")
      .then((d) => setFreezes(d.freezes || []))
      .catch((e) => toast.error(e.response?.data?.detail || e.message))
      .finally(() => setLoading(false));
  };

  useEffect(() => { reload(); /* eslint-disable-next-line */ }, []);

  useEffect(() => {
    api.get("/clients").then((d) => {
      setClients(Array.isArray(d) ? d : (d?.clients || []));
    }).catch(() => {});
    // eslint-disable-next-line
  }, []);

  const remove = async (id) => {
    try {
      await api.del(`/change-freezes/${id}`);
      toast.success("Freeze removed");
      setDeleteTarget(null);
      reload();
    } catch (e) { toast.error(e.message); }
  };

  const save = async (draft) => {
    try {
      if (draft.id) {
        await api.put(`/change-freezes/${draft.id}`, draft);
      } else {
        await api.post(`/change-freezes`, draft);
      }
      toast.success("Saved");
      setEditorOpen(false);
      reload();
    } catch (e) {
      toast.error(e.response?.data?.detail || e.message);
    }
  };

  const now = new Date();
  const activeCount = freezes.filter(f => {
    const s = new Date(f.starts_at), e = new Date(f.ends_at);
    return f.active && s <= now && e >= now;
  }).length;
  const upcomingCount = freezes.filter(f => {
    const s = new Date(f.starts_at);
    return f.active && s > now;
  }).length;
  const visibleFreezes = activeOnly
    ? freezes.filter(f => f.active && new Date(f.starts_at) <= now && new Date(f.ends_at) >= now)
    : freezes;

  return (
    <PageShell>
      <div className="space-y-5" data-testid="change-freeze-page">
        <OperationalPageHeader
          eyebrow="Change control"
          title="Change freeze calendar"
          description="Protect sensitive client and MSP-wide windows by blocking automation until the approved change window reopens."
          icon={Snowflake}
          tone="sky"
          actions={<>
            <Button variant="outline" size="sm" onClick={() => navigate("/change-management")} data-testid="freeze-change-management"><GitBranch className="mr-1.5 h-3.5 w-3.5" />Change management</Button>
            <Button variant="outline" size="sm" onClick={reload} disabled={loading} data-testid="freeze-refresh"><RefreshCw className={`mr-1.5 h-3.5 w-3.5 ${loading ? "animate-spin" : ""}`} />Refresh</Button>
            <Button size="sm" onClick={() => { setEditing(blankDraft()); setEditorOpen(true); }} data-testid="freeze-new-btn"><Plus className="mr-1.5 h-3.5 w-3.5" />New freeze</Button>
          </>}
        />

        <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
          <HeroTile label="Active now" value={activeCount} icon={Shield} glow="rose" active={activeOnly} onClick={() => setActiveOnly(true)} testId="freeze-stat-active" />
          <HeroTile label="Upcoming" value={upcomingCount} icon={Calendar} glow="amber" testId="freeze-stat-upcoming" />
          <HeroTile label="All windows" value={freezes.length} icon={Snowflake} glow="sky" active={!activeOnly} onClick={() => setActiveOnly(false)} testId="freeze-stat-total" />
        </div>

        <div className="flex items-center gap-2">
          <Switch checked={activeOnly} onCheckedChange={setActiveOnly} data-testid="freeze-active-only" />
          <span className="text-xs text-muted-foreground">Show only currently active</span>
        </div>

        {loading ? (
          <div className="py-12 flex items-center justify-center gap-2 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 animate-spin" />Loading…</div>
        ) : visibleFreezes.length === 0 ? (
          <Card><CardContent className="p-8 text-center text-sm text-muted-foreground">
            <Snowflake className="w-10 h-10 mx-auto mb-2 opacity-50" />
            {activeOnly ? "No freeze windows are active right now." : "No freeze windows. Create one to protect a sensitive window."}
          </CardContent></Card>
        ) : (
          <div className="space-y-2" data-testid="freeze-list">
            {visibleFreezes.map((f) => <FreezeRow key={f.id} f={f} onEdit={() => { setEditing(f); setEditorOpen(true); }} onDelete={() => setDeleteTarget(f)} />)}
          </div>
        )}

        {editorOpen && (
          <FreezeEditor open={editorOpen} initial={editing} clients={clients} onClose={() => setEditorOpen(false)} onSave={save} />
        )}
        <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Remove this freeze window?</AlertDialogTitle>
              <AlertDialogDescription>This removes the automation safeguard for {deleteTarget?.client_name || "all clients"}. This action is recorded in the change-control history.</AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Keep freeze</AlertDialogCancel>
              <AlertDialogAction className="bg-destructive text-destructive-foreground hover:bg-destructive/90" onClick={() => deleteTarget && remove(deleteTarget.id)}>Remove freeze</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </PageShell>
  );
}

function FreezeRow({ f, onEdit, onDelete }) {
  const now = new Date();
  const s = new Date(f.starts_at), e = new Date(f.ends_at);
  const isActiveNow = f.active && s <= now && e >= now;
  const isUpcoming = f.active && s > now;
  const isPast = e < now;
  const stateColor = isActiveNow ? "rose" : isUpcoming ? "amber" : isPast ? "zinc" : "sky";
  const stateLabel = isActiveNow ? "ACTIVE NOW" : isUpcoming ? "UPCOMING" : isPast ? "ENDED" : "INACTIVE";
  const tone = {
    rose: { border: "border-l-rose-500/60", icon: "text-rose-400", badge: "border-rose-500/40 text-rose-400" },
    amber: { border: "border-l-amber-500/60", icon: "text-amber-400", badge: "border-amber-500/40 text-amber-400" },
    zinc: { border: "border-l-zinc-500/60", icon: "text-zinc-400", badge: "border-zinc-500/40 text-zinc-400" },
    sky: { border: "border-l-sky-500/60", icon: "text-sky-400", badge: "border-sky-500/40 text-sky-400" },
  }[stateColor];

  return (
    <Card data-testid={`freeze-row-${f.id}`} className={`border-l-2 ${tone.border}`}>
      <CardContent className="p-3 flex items-center gap-3 flex-wrap">
        <Snowflake className={`w-4 h-4 ${tone.icon}`} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-medium truncate">{f.title}</span>
            <Badge variant="outline" className={`text-[10px] ${tone.badge}`}>{stateLabel}</Badge>
            {!f.active && <Badge variant="outline" className="text-[10px]">Disabled</Badge>}
          </div>
          <div className="text-[11px] text-muted-foreground">
            {f.client_name} · {s.toLocaleString()} → {e.toLocaleString()}
          </div>
          <div className="flex flex-wrap gap-1 mt-1">
            {(f.kinds || []).map(k => <Badge key={k} variant="outline" className="text-[10px]">{k}</Badge>)}
          </div>
          {f.reason && <div className="text-[11px] text-muted-foreground italic mt-1">"{f.reason}"</div>}
        </div>
        <div className="flex items-center gap-1">
          <Button size="sm" variant="ghost" onClick={onEdit} data-testid={`freeze-edit-${f.id}`}><Pencil className="w-3 h-3" /></Button>
          <Button size="sm" variant="ghost" onClick={onDelete} data-testid={`freeze-delete-${f.id}`}><Trash2 className="w-3 h-3 text-rose-400" /></Button>
        </div>
      </CardContent>
    </Card>
  );
}

function blankDraft() {
  const start = new Date();
  start.setMinutes(0, 0, 0);
  start.setHours(start.getHours() + 1);
  const end = new Date(start.getTime() + 4 * 3600 * 1000);
  return {
    title: "",
    client_id: "",
    starts_at: toLocalIsoInput(start),
    ends_at: toLocalIsoInput(end),
    kinds: ["patch", "reboot", "script", "broadcast"],
    reason: "",
    active: true,
  };
}

function toLocalIsoInput(d) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function ClientScopePicker({ clients, value, onChange }) {
  const [open, setOpen] = useState(false);
  const selected = clients.find((client) => client.id === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button type="button" variant="outline" role="combobox" aria-expanded={open} className="h-10 w-full justify-between font-normal" data-testid="freeze-client">
          <span className="truncate">{selected?.name || "All clients (MSP-wide)"}</span>
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0" align="start">
        <Command>
          <CommandInput placeholder="Search clients..." />
          <CommandList className="max-h-72">
            <CommandEmpty>No client found.</CommandEmpty>
            <CommandGroup heading="Scope">
              <CommandItem value="All clients MSP-wide" onSelect={() => { onChange(""); setOpen(false); }}>
                <Check className={`mr-2 h-4 w-4 ${!value ? "opacity-100" : "opacity-0"}`} />All clients (MSP-wide)
              </CommandItem>
            </CommandGroup>
            <CommandGroup heading="Clients">
              {clients.map((client) => (
                <CommandItem key={client.id} value={`${client.name} ${client.email || ""}`} onSelect={() => { onChange(client.id); setOpen(false); }}>
                  <Check className={`mr-2 h-4 w-4 ${value === client.id ? "opacity-100" : "opacity-0"}`} />
                  <span className="truncate">{client.name}</span>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

function FreezeEditor({ open, initial, clients, onClose, onSave }) {
  const [d, setD] = useState(() => ({
    ...initial,
    starts_at: initial?.starts_at ? toLocalIsoInput(new Date(initial.starts_at)) : "",
    ends_at: initial?.ends_at ? toLocalIsoInput(new Date(initial.ends_at)) : "",
  }));
  const set = (k, v) => setD((x) => ({ ...x, [k]: v }));
  const toggleKind = (k) => set("kinds", d.kinds?.includes(k) ? d.kinds.filter(x => x !== k) : [...(d.kinds || []), k]);

  const submit = () => {
    if (!d.title?.trim()) return toast.error("Title required");
    if (!d.starts_at || !d.ends_at) return toast.error("Start and end required");
    if (new Date(d.ends_at) <= new Date(d.starts_at)) return toast.error("End must be after start");
    onSave({
      ...d,
      client_id: d.client_id || null,
      starts_at: new Date(d.starts_at).toISOString(),
      ends_at: new Date(d.ends_at).toISOString(),
    });
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-h-[92vh] max-w-xl overflow-y-auto border-sky-400/20 bg-background p-0" data-testid="freeze-editor">
        <DialogHeader className="border-b border-sky-400/15 bg-[linear-gradient(135deg,rgba(14,165,233,0.12),rgba(15,23,42,0.92))] px-6 py-5 pr-14">
          <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-sky-300">Change control</p>
          <DialogTitle className="mt-1 flex items-center gap-2 text-xl"><span className="flex h-9 w-9 items-center justify-center rounded-xl border border-sky-400/25 bg-sky-400/10"><Snowflake className="h-4 w-4 text-sky-300" /></span>{d.id ? "Edit freeze window" : "Create freeze window"}</DialogTitle>
          <DialogDescription className="mt-2">Automation matching this scope and change type will pause for the approved window, leaving the exception auditable.</DialogDescription>
        </DialogHeader>
        <div className="space-y-4 px-6 py-5">
          <div>
            <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Title</label>
            <Input value={d.title || ""} onChange={(e) => set("title", e.target.value)} placeholder="EOFY blackout · Acme Corp" data-testid="freeze-title" />
          </div>
          <div>
            <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Client (leave blank = all clients)</label>
            <div className="mt-1"><ClientScopePicker clients={clients} value={d.client_id || ""} onChange={(value) => set("client_id", value)} /></div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Starts</label>
              <Input type="datetime-local" value={d.starts_at || ""} onChange={(e) => set("starts_at", e.target.value)} data-testid="freeze-starts" />
            </div>
            <div>
              <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Ends</label>
              <Input type="datetime-local" value={d.ends_at || ""} onChange={(e) => set("ends_at", e.target.value)} data-testid="freeze-ends" />
            </div>
          </div>
          <div>
            <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Block kinds</label>
            <div className="flex flex-wrap gap-2 mt-1">
              {KIND_OPTIONS.map((k) => {
                const on = d.kinds?.includes(k.v);
                return (
                  <button
                    key={k.v}
                    type="button"
                    onClick={() => toggleKind(k.v)}
                    className={`text-[11px] px-2 py-1 rounded border transition-colors ${on ? "bg-sky-500/15 text-sky-300 border-sky-500/40" : "border-border/40 text-muted-foreground hover:bg-muted/50"}`}
                    data-testid={`freeze-kind-${k.v}`}
                  >
                    {k.label}
                  </button>
                );
              })}
            </div>
          </div>
          <div>
            <label className="text-[10px] uppercase tracking-widest text-muted-foreground">Reason</label>
            <Textarea rows={3} value={d.reason || ""} onChange={(e) => set("reason", e.target.value)} placeholder="Stocktake weekend, no IT changes" data-testid="freeze-reason" />
          </div>
          <div className="flex items-center gap-2">
            <Switch checked={d.active !== false} onCheckedChange={(v) => set("active", v)} data-testid="freeze-active" />
            <span className="text-xs text-muted-foreground">Active</span>
          </div>
        </div>
        <DialogFooter className="border-t border-border/70 bg-muted/10 px-6 py-4">
          <Button variant="outline" size="sm" onClick={onClose}>Cancel</Button>
          <Button size="sm" onClick={submit} data-testid="freeze-save">{d.id ? "Save audited changes" : "Create freeze window"}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Building2, Users, Monitor, DollarSign, Plus, ChevronRight, TrendingUp } from "lucide-react";

const TIER_COLORS = { enterprise: "#8b5cf6", professional: "#3b82f6", standard: "#6b7280" };
const FEATURE_LIST = ["tickets", "devices", "clients", "reports", "security", "patching", "backup", "automation", "ai_copilot", "white_label"];

export default function ChannelModePage() {
  const { token } = useAuth();
  const headers = { Authorization: `Bearer ${token}` };
  const [data, setData] = useState(null);
  const [revenue, setRevenue] = useState(null);
  const [selected, setSelected] = useState(null);
  const [tab, setTab] = useState("tenants");
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState({ name: "", admin_email: "", tier: "standard" });

  useEffect(() => {
    axios.get(`${API}/channel-mode/tenants`, { headers }).then(r => setData(r.data));
    axios.get(`${API}/channel-mode/revenue`, { headers }).then(r => setRevenue(r.data));
  }, []);

  const createTenant = async () => {
    await axios.post(`${API}/channel-mode/tenant`, form, { headers });
    setShowCreate(false);
    setForm({ name: "", admin_email: "", tier: "standard" });
    axios.get(`${API}/channel-mode/tenants`, { headers }).then(r => setData(r.data));
  };

  if (!data) return <div className="animate-pulse p-8">Loading Channel Mode...</div>;
  const { tenants, summary } = data;

  return (
    <div data-testid="channel-mode-page">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2"><Building2 size={24} /> Channel / MSP-of-MSPs</h1>
          <p className="text-sm text-[var(--muted)] mt-1">Manage white-label tenant MSPs from a single pane</p>
        </div>
        <button data-testid="create-tenant-btn" onClick={() => setShowCreate(true)} className="px-3 py-1.5 rounded-lg text-sm font-medium flex items-center gap-1.5" style={{ background: "var(--accent)", color: "white" }}>
          <Plus size={14} /> New Tenant
        </button>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-6">
        {[
          { label: "Total Tenants", value: summary.total_tenants, icon: Building2, color: "#3b82f6" },
          { label: "Active", value: summary.active, icon: Users, color: "#10b981" },
          { label: "Total Endpoints", value: summary.total_endpoints?.toLocaleString(), icon: Monitor, color: "#8b5cf6" },
          { label: "Total MRR", value: `$${summary.total_mrr?.toLocaleString()}`, icon: DollarSign, color: "#f97316" },
          { label: "Avg Margin", value: `${summary.avg_margin}%`, icon: TrendingUp, color: "#10b981" },
        ].map((s, i) => (
          <div key={`k-${i}`} className="rounded-xl p-4 border" style={{ background: "var(--card)", borderColor: "var(--border)" }}>
            <div className="flex items-center gap-2 mb-2"><s.icon size={14} style={{ color: s.color }} /><span className="text-xs text-[var(--muted)]">{s.label}</span></div>
            <div className="text-xl font-bold">{s.value}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="flex gap-1 mb-4">
        {["tenants", "revenue"].map(t => (
          <button key={t} onClick={() => setTab(t)} className={`px-3 py-1.5 rounded-lg text-sm capitalize ${tab === t ? "text-white" : "text-[var(--muted)]"}`} style={{ background: tab === t ? "var(--accent)" : "var(--secondary)" }}>{t}</button>
        ))}
      </div>

      {tab === "tenants" && (
        <div className="space-y-2">
          {tenants.map(t => (
            <div key={t.tenant_id} data-testid={`tenant-${t.tenant_id}`} onClick={() => setSelected(selected?.tenant_id === t.tenant_id ? null : t)} className="rounded-xl p-4 border cursor-pointer transition-colors hover:border-[var(--accent)]" style={{ background: "var(--card)", borderColor: selected?.tenant_id === t.tenant_id ? "var(--accent)" : "var(--border)" }}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center text-white font-bold text-sm" style={{ background: t.branding?.primary_color || "#3b82f6" }}>{t.name.charAt(0)}</div>
                  <div>
                    <div className="font-medium">{t.name}</div>
                    <div className="text-xs text-[var(--muted)]">{t.domain}</div>
                  </div>
                </div>
                <div className="flex items-center gap-4 text-sm">
                  <span className="px-2 py-0.5 rounded text-xs font-medium capitalize" style={{ background: TIER_COLORS[t.tier] + "22", color: TIER_COLORS[t.tier] }}>{t.tier}</span>
                  <span className="text-[var(--muted)]"><Monitor size={12} className="inline mr-1" />{t.endpoint_count}</span>
                  <span className="font-medium text-emerald-400">${t.mrr?.toLocaleString()}/mo</span>
                  <span className={`px-2 py-0.5 rounded text-xs ${t.status === "active" ? "bg-emerald-500/20 text-emerald-400" : "bg-yellow-500/20 text-yellow-400"}`}>{t.status}</span>
                  <ChevronRight size={14} className="text-[var(--muted)]" />
                </div>
              </div>
              {selected?.tenant_id === t.tenant_id && (
                <div className="mt-4 pt-4 border-t grid grid-cols-2 md:grid-cols-4 gap-4 text-sm" style={{ borderColor: "var(--border)" }}>
                  <div><span className="text-[var(--muted)] text-xs block">Technicians</span>{t.technicians || "N/A"}</div>
                  <div><span className="text-[var(--muted)] text-xs block">Clients</span>{t.clients_count || "N/A"}</div>
                  <div><span className="text-[var(--muted)] text-xs block">Margin</span>{t.margin_pct}%</div>
                  <div><span className="text-[var(--muted)] text-xs block">Admin</span>{t.admin_email}</div>
                  <div className="col-span-full"><span className="text-[var(--muted)] text-xs block mb-1">Features Enabled</span>
                    <div className="flex flex-wrap gap-1">{(t.features_enabled || []).map(f => <span key={f} className="px-2 py-0.5 rounded text-xs" style={{ background: "var(--secondary)" }}>{f}</span>)}</div>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {tab === "revenue" && revenue && (
        <div className="space-y-4">
          <div className="rounded-xl p-4 border" style={{ background: "var(--card)", borderColor: "var(--border)" }}>
            <h3 className="text-sm font-medium mb-3">Monthly Revenue vs Cost</h3>
            <div className="flex items-end gap-2 h-40">
              {(revenue.monthly_trend || []).map((m, i) => (
                <div key={`k-${i}`} className="flex-1 flex flex-col items-center gap-1">
                  <div className="w-full flex flex-col items-center gap-0.5">
                    <div className="w-full rounded-t bg-emerald-500" style={{ height: `${(m.revenue / 80000) * 100}px` }} />
                    <div className="w-full rounded-t bg-red-400/50" style={{ height: `${(m.cost / 80000) * 100}px` }} />
                  </div>
                  <span className="text-[10px] text-[var(--muted)]">{m.month}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="rounded-xl p-4 border" style={{ background: "var(--card)", borderColor: "var(--border)" }}>
            <h3 className="text-sm font-medium mb-3">Revenue by Tier</h3>
            <div className="space-y-2">
              {Object.entries(revenue.by_tier || {}).map(([tier, val]) => (
                <div key={tier} className="flex items-center gap-3">
                  <span className="text-sm capitalize w-24">{tier}</span>
                  <div className="flex-1 h-6 rounded-full overflow-hidden" style={{ background: "var(--secondary)" }}>
                    <div className="h-full rounded-full" style={{ width: `${(val / Math.max(...Object.values(revenue.by_tier))) * 100}%`, background: TIER_COLORS[tier] || "#6b7280" }} />
                  </div>
                  <span className="text-sm font-medium w-20 text-right">${val?.toLocaleString()}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Create tenant modal */}
      {showCreate && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowCreate(false)}>
          <div className="rounded-xl p-6 w-full max-w-md" style={{ background: "var(--card)" }} onClick={e => e.stopPropagation()}>
            <h2 className="text-lg font-bold mb-4">Create New Tenant</h2>
            <div className="space-y-3">
              <div>
                <label className="text-xs text-[var(--muted)] block mb-1">MSP Name</label>
                <input data-testid="tenant-name-input" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm" style={{ background: "var(--secondary)", border: "1px solid var(--border)" }} placeholder="Acme IT Services" />
              </div>
              <div>
                <label className="text-xs text-[var(--muted)] block mb-1">Admin Email</label>
                <input data-testid="tenant-email-input" value={form.admin_email} onChange={e => setForm({ ...form, admin_email: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm" style={{ background: "var(--secondary)", border: "1px solid var(--border)" }} placeholder="admin@acmeit.com" />
              </div>
              <div>
                <label className="text-xs text-[var(--muted)] block mb-1">Tier</label>
                <select data-testid="tenant-tier-select" value={form.tier} onChange={e => setForm({ ...form, tier: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm" style={{ background: "var(--secondary)", border: "1px solid var(--border)" }}>
                  <option value="standard">Standard</option>
                  <option value="professional">Professional</option>
                  <option value="enterprise">Enterprise</option>
                </select>
              </div>
            </div>
            <div className="flex gap-2 mt-4">
              <button onClick={() => setShowCreate(false)} className="px-4 py-2 rounded-lg text-sm" style={{ background: "var(--secondary)" }}>Cancel</button>
              <button data-testid="submit-tenant-btn" onClick={createTenant} className="px-4 py-2 rounded-lg text-sm text-white" style={{ background: "var(--accent)" }}>Create Tenant</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import {
  Activity, Heart, Shield, Monitor, DollarSign, AlertTriangle, RefreshCw, Loader2, Bell, Camera, Check,
  HardDrive, Ticket, CreditCard, Lock, Search, Wifi
} from "lucide-react";
import { ResponsiveContainer, RadarChart, Radar, PolarGrid, PolarAngleAxis, PolarRadiusAxis } from "recharts";
import HeroTile from "@/components/HeroTile";

const chartStyle = { backgroundColor: "hsl(217, 33%, 17%)", border: "1px solid hsl(217, 33%, 25%)", borderRadius: "8px", color: "hsl(210, 40%, 98%)" };

const STATUS_CONFIG = {
  thriving: { color: "bg-emerald-500/20 text-emerald-400", ring: "ring-emerald-500/30", gradient: "from-emerald-500 to-emerald-600", label: "Thriving" },
  healthy: { color: "bg-blue-500/20 text-blue-400", ring: "ring-blue-500/30", gradient: "from-blue-500 to-blue-600", label: "Healthy" },
  needs_attention: { color: "bg-amber-500/20 text-amber-400", ring: "ring-amber-500/30", gradient: "from-amber-500 to-amber-600", label: "Needs Attention" },
  at_risk: { color: "bg-orange-500/20 text-orange-400", ring: "ring-orange-500/30", gradient: "from-orange-500 to-orange-600", label: "At Risk" },
  critical: { color: "bg-red-500/20 text-red-400", ring: "ring-red-500/30", gradient: "from-red-500 to-red-600", label: "Critical" },
  not_assessed: { color: "bg-slate-500/20 text-slate-300", ring: "ring-slate-500/30", gradient: "from-slate-500 to-slate-600", label: "Not Assessed" },
};

function HealthGauge({ score, size = 64 }) {
  const assessed = Number.isFinite(score);
  const color = !assessed ? "#94a3b8" : score >= 85 ? "#22c55e" : score >= 70 ? "#3b82f6" : score >= 50 ? "#eab308" : score >= 30 ? "#f97316" : "#ef4444";
  const pct = assessed ? Math.min(100, Math.max(0, score)) : 0;
  const r = (size / 2) - 6;
  const dash = pct * 2.51;
  return (
    <div className="relative" style={{ width: size, height: size }}>
      <svg className="-rotate-90" width={size} height={size} viewBox="0 0 100 100">
        <circle cx="50" cy="50" r="40" fill="none" stroke="currentColor" className="text-muted/15" strokeWidth="7" />
        <circle cx="50" cy="50" r="40" fill="none" stroke={color} strokeWidth="7" strokeDasharray={`${dash} ${251 - dash}`} strokeLinecap="round" />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center text-lg font-black" style={{ color }}>{assessed ? score : "—"}</span>
    </div>
  );
}

function MetricBar({ label, value, icon: Icon, color }) {
  return (
    <div className="flex items-center gap-3">
      <div className={`w-7 h-7 rounded-md flex items-center justify-center ${color.split(" ")[0]}`}><Icon className={`w-3.5 h-3.5 ${color.split(" ")[1]}`} /></div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between mb-0.5"><span className="text-[11px] text-muted-foreground">{label}</span><span className="text-xs font-bold">{Number.isFinite(value) ? value : "—"}</span></div>
        <Progress value={Number.isFinite(value) ? value : 0} className="h-1" />
      </div>
    </div>
  );
}

export default function ClientHealthPage({ embedded = false }) {
  const { token } = useAuth();
  const [dashboard, setDashboard] = useState(null);
  const [allScores, setAllScores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState(null);
  const [clientDetail, setClientDetail] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [settingsDialog, setSettingsDialog] = useState(false);
  const [alertConfig, setAlertConfig] = useState(null);
  const [snapshotting, setSnapshotting] = useState(false);
  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [dRes, sRes] = await Promise.all([
        axios.get(`${API}/client-health/dashboard`, { headers }),
        axios.get(`${API}/client-health/scores`, { headers }),
      ]);
      setDashboard(dRes.data);
      setAllScores(sRes.data);
    } catch { toast.error("Failed to load health data"); }
    finally { setLoading(false); }
  }, [token]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const loadClientDetail = async (clientId) => {
    setDetailLoading(true);
    try {
      const res = await axios.get(`${API}/client-health/${clientId}/detail`, { headers });
      setClientDetail(res.data);
    } catch { toast.error("Failed to load client detail"); }
    finally { setDetailLoading(false); }
  };

  const handleSnapshot = async () => {
    setSnapshotting(true);
    try {
      const res = await axios.post(`${API}/client-health/snapshot`, {}, { headers });
      toast.success(res.data.message);
    } catch { toast.error("Failed to take snapshot"); }
    finally { setSnapshotting(false); }
  };

  const loadAlertConfig = async () => {
    try { const r = await axios.get(`${API}/client-health/alert-config`, { headers }); setAlertConfig(r.data); }
    catch { setAlertConfig({ critical_threshold: 30, warning_threshold: 50, notify_on_decline: true, decline_amount: 10, notify_email: "", auto_create_ticket: false }); }
  };

  const saveAlertConfig = async () => {
    try { await axios.put(`${API}/client-health/alert-config`, alertConfig, { headers }); toast.success("Alert settings saved"); setSettingsDialog(false); }
    catch { toast.error("Failed"); }
  };

  if (loading || !dashboard) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin" /></div>;

  const d = dashboard;
  const dist = d.distribution || {};
  const filtered = allScores.filter(c => {
    if (statusFilter !== "all" && c.status !== statusFilter) return false;
    if (search && !c.client_name.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  const radarData = clientDetail ? [
    { metric: "Tickets", value: clientDetail.metrics?.ticket_health },
    { metric: "Devices", value: clientDetail.metrics?.device_health },
    { metric: "Payments", value: clientDetail.metrics?.payment_health },
    { metric: "Backups", value: clientDetail.metrics?.backup_health },
    { metric: "Security", value: clientDetail.metrics?.security_health },
    ...(clientDetail.metrics?.network_health != null ? [{ metric: "Network", value: clientDetail.metrics.network_health }] : []),
    ...(clientDetail.metrics?.m365_hygiene != null ? [{ metric: "M365", value: clientDetail.metrics.m365_hygiene }] : []),
  ].filter(({ value }) => Number.isFinite(value)) : [];
  const hasAverageHealth = Number.isFinite(d.avg_health);
  const averageHealthTone = !hasAverageHealth ? "text-slate-300" : d.avg_health >= 70 ? "text-emerald-400" : d.avg_health >= 50 ? "text-amber-400" : "text-red-400";

  return (
    <div className="space-y-5" data-testid="client-health-page">
      {/* Header */}
      <div className={`flex items-center ${embedded ? "justify-end" : "justify-between"}`}>
        {!embedded && <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
            <div className="h-10 w-10 rounded-lg bg-gradient-to-br from-emerald-500 to-cyan-600 flex items-center justify-center"><Heart className="w-5 h-5 text-white" /></div>
            Client Health Dashboard
          </h1>
          <p className="text-muted-foreground mt-1">{d.assessed_clients || 0} of {d.total} clients assessed | Average health: <span className={`font-bold ${averageHealthTone}`}>{hasAverageHealth ? `${d.avg_health}/100` : "Not assessed"}</span></p>
        </div>}
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={() => { loadAlertConfig(); setSettingsDialog(true); }} data-testid="alert-settings-btn"><Bell className="w-4 h-4 mr-1" />Alert Settings</Button>
          <Button variant="outline" size="sm" onClick={handleSnapshot} disabled={snapshotting} data-testid="take-snapshot-btn">
            {snapshotting ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Camera className="w-4 h-4 mr-1" />}Snapshot
          </Button>
          <Button variant="outline" size="sm" onClick={fetchData}><RefreshCw className="w-4 h-4 mr-1" />Refresh</Button>
        </div>
      </div>

      {/* KPI Row — gradient hero tiles */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-3">
        <div className="col-span-2 relative overflow-hidden rounded-lg border bg-gradient-to-br from-violet-500/20 to-fuchsia-600/10 border-violet-500/30 text-violet-300 shadow-lg shadow-violet-500/20 p-4 flex items-center gap-4">
          <div className="absolute -top-6 -right-6 w-20 h-20 rounded-full bg-current opacity-10 blur-2xl" />
          <div className="relative"><HealthGauge score={d.avg_health} size={72} /></div>
          <div className="relative">
            <p className="text-[10px] uppercase tracking-widest opacity-80">Average Health</p>
            <p className="text-3xl font-bold font-mono tracking-tighter">{hasAverageHealth ? d.avg_health : "—"}{hasAverageHealth && <span className="text-sm opacity-70">/100</span>}</p>
            <p className="text-[10px] opacity-70">{d.assessed_clients || 0} assessed of {d.total}</p>
          </div>
        </div>
        {["thriving", "healthy", "needs_attention", "at_risk", "critical", "not_assessed"].map(s => {
          const cfg = STATUS_CONFIG[s];
          const count = dist[s] || 0;
          const isActive = statusFilter === s;
          const glow = ({ thriving: "emerald", healthy: "cyan", needs_attention: "amber", at_risk: "amber", critical: "rose", not_assessed: "slate" })[s];
          return <HeroTile key={s} label={cfg.label} value={count} icon={Heart} glow={glow} subtitle={isActive ? "Filter active" : "Filter client health"} onClick={() => setStatusFilter(statusFilter === s ? "all" : s)} active={isActive} testId={`client-health-${s}`} />;
        })}
      </div>

      {/* Revenue Alert */}
      {d.at_risk_revenue > 0 && (
        <Card className="border-red-500/20 bg-red-500/5">
          <CardContent className="py-3 flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-red-500/20 flex items-center justify-center"><DollarSign className="w-5 h-5 text-red-400" /></div>
            <div className="flex-1">
              <p className="text-sm font-bold text-red-400">${d.at_risk_revenue?.toLocaleString()} Monthly Revenue at Risk</p>
              <p className="text-xs text-muted-foreground">{(d.at_risk || []).length} clients with health below 50 — proactive outreach recommended</p>
            </div>
            <Badge className="bg-red-500/20 text-red-400">{((d.at_risk_revenue / Math.max(d.total_monthly_revenue, 1)) * 100).toFixed(1)}% of MRR</Badge>
          </CardContent>
        </Card>
      )}

      {/* Active Alerts */}
      {(d.alerts || []).length > 0 && (
        <Card className="border-amber-500/20">
          <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><AlertTriangle className="w-4 h-4 text-amber-400" />Active Health Alerts ({d.alerts.length})</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
              {d.alerts.slice(0, 6).map(a => (
                <div key={a.id} className={`p-2.5 rounded-lg border ${a.severity === "critical" ? "bg-red-500/5 border-red-500/20" : "bg-amber-500/5 border-amber-500/20"} cursor-pointer hover:ring-1 ring-border/40`}
                  onClick={() => { setSelectedClient(allScores.find(s => s.client_id === a.client_id)); loadClientDetail(a.client_id); }}>
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold">{a.client_name}</span>
                    <Badge className={`text-[9px] ${a.severity === "critical" ? "bg-red-500/20 text-red-400" : "bg-amber-500/20 text-amber-400"}`}>{Number.isFinite(a.health_score) ? a.health_score : "—"}</Badge>
                  </div>
                  <p className="text-[11px] text-muted-foreground mt-1">{a.message}</p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      <div className="grid grid-cols-[1fr_380px] gap-4">
        {/* Left: Client Table */}
        <div className="space-y-3">
          <div className="flex gap-3">
            <div className="relative flex-1"><Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><Input placeholder="Search clients..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9" data-testid="health-search" /></div>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-[160px]"><SelectValue /></SelectTrigger>
              <SelectContent><SelectItem value="all">All Statuses</SelectItem>{Object.entries(STATUS_CONFIG).map(([k, v]) => <SelectItem key={k} value={k}>{v.label}</SelectItem>)}</SelectContent>
            </Select>
          </div>

          <Card>
            <CardContent className="p-0">
              <ScrollArea className="h-[520px]">
                <Table>
                  <TableHeader>
                    <TableRow><TableHead>Client</TableHead><TableHead>Health</TableHead><TableHead>Status</TableHead><TableHead className="text-center">Tickets</TableHead><TableHead className="text-center">Devices</TableHead><TableHead className="text-right">MRR</TableHead><TableHead>Risk Factors</TableHead></TableRow>
                  </TableHeader>
                  <TableBody>
                    {filtered.map(c => {
                      const cfg = STATUS_CONFIG[c.status] || STATUS_CONFIG.not_assessed;
                      const isSelected = selectedClient?.client_id === c.client_id;
                      return (
                        <TableRow key={c.client_id} className={`cursor-pointer transition-all ${isSelected ? "bg-primary/5 ring-1 ring-primary/20" : "hover:bg-muted/30"}`}
                          onClick={() => { setSelectedClient(c); loadClientDetail(c.client_id); }} data-testid={`health-row-${c.client_id}`}>
                          <TableCell>
                            <div className="font-medium text-sm">{c.client_name}</div>
                            {c.tier && <Badge variant="outline" className="text-[9px] mt-0.5">{c.tier}</Badge>}
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-2 w-20">
                              <Progress value={Number.isFinite(c.health_score) ? c.health_score : 0} className="h-2" />
                              <span className="text-xs font-mono font-bold">{Number.isFinite(c.health_score) ? c.health_score : "—"}</span>
                            </div>
                          </TableCell>
                          <TableCell><Badge className={`${cfg.color} text-[10px]`}>{cfg.label}</Badge></TableCell>
                          <TableCell className="text-center">
                            <span className="text-xs font-mono">{c.details?.open_tickets || 0}</span>
                            {c.details?.critical_tickets > 0 && <span className="text-[9px] text-red-400 ml-0.5">({c.details.critical_tickets}!)</span>}
                          </TableCell>
                          <TableCell className="text-center text-xs font-mono">{c.details?.online_devices || 0}/{c.details?.devices || 0}</TableCell>
                          <TableCell className="text-right text-xs font-mono">${(c.mrr || 0).toLocaleString()}</TableCell>
                          <TableCell>
                            <div className="flex gap-0.5">
                              {(c.risk_factors || []).slice(0, 2).map((rf, i) => (
                                <Badge key={i} className={`text-[8px] ${rf.severity === "critical" ? "bg-red-500/20 text-red-400" : "bg-amber-500/20 text-amber-400"}`}>{rf.factor.slice(0, 25)}</Badge>
                              ))}
                            </div>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </ScrollArea>
            </CardContent>
          </Card>
        </div>

        {/* Right: Client Detail Panel */}
        <div className="space-y-3">
          {!selectedClient ? (
            <Card className="border-dashed h-full flex items-center justify-center">
              <CardContent className="text-center py-16">
                <Heart className="w-12 h-12 mx-auto text-muted-foreground/20 mb-3" />
                <p className="font-medium">Select a Client</p>
                <p className="text-xs text-muted-foreground mt-1">Click a client row to view detailed health breakdown</p>
              </CardContent>
            </Card>
          ) : detailLoading ? (
            <Card className="h-full flex items-center justify-center"><CardContent><Loader2 className="w-8 h-8 animate-spin mx-auto" /></CardContent></Card>
          ) : clientDetail ? (
            <>
              <Card className={`border-border/40 ring-1 ${STATUS_CONFIG[clientDetail.status]?.ring || ""}`}>
                <CardContent className="pt-4 pb-3">
                  <div className="flex items-center gap-3 mb-3">
                    <HealthGauge score={clientDetail.health_score} size={56} />
                    <div className="flex-1">
                      <h3 className="font-bold text-lg">{clientDetail.client_name}</h3>
                      <div className="flex items-center gap-2">
                        <Badge className={(STATUS_CONFIG[clientDetail.status] || STATUS_CONFIG.not_assessed).color + " text-[10px]"}>{(STATUS_CONFIG[clientDetail.status] || STATUS_CONFIG.not_assessed).label}</Badge>
                        {clientDetail.tier && <Badge variant="outline" className="text-[9px]">{clientDetail.tier}</Badge>}
                        {clientDetail.industry && <Badge variant="outline" className="text-[9px]">{clientDetail.industry}</Badge>}
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-lg font-bold">${(clientDetail.mrr || 0).toLocaleString()}</p>
                      <p className="text-[10px] text-muted-foreground">MRR</p>
                    </div>
                  </div>

                  {/* Radar Chart */}
                  <div className="h-[180px]">
                    {radarData.length ? <ResponsiveContainer width="100%" height="100%">
                      <RadarChart data={radarData} cx="50%" cy="50%" outerRadius={65}>
                        <PolarGrid stroke="hsl(var(--border))" />
                        <PolarAngleAxis dataKey="metric" tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 10 }} />
                        <PolarRadiusAxis domain={[0, 100]} tick={false} axisLine={false} />
                        <Radar name="Health" dataKey="value" stroke="#06b6d4" fill="#06b6d4" fillOpacity={0.15} strokeWidth={2} />
                      </RadarChart>
                    </ResponsiveContainer> : <div className="h-full flex items-center justify-center text-center text-xs text-muted-foreground px-8">No health dimensions have verified source evidence yet.</div>}
                  </div>
                </CardContent>
              </Card>

              {/* Metric Breakdown */}
              <Card>
                <CardHeader className="pb-2"><CardTitle className="text-xs uppercase tracking-wider text-muted-foreground">Health Breakdown</CardTitle></CardHeader>
                <CardContent className="space-y-2.5">
                  <MetricBar label="Ticket Health" value={clientDetail.metrics?.ticket_health} icon={Ticket} color="bg-blue-500/15 text-blue-400" />
                  <MetricBar label="Device Uptime" value={clientDetail.metrics?.device_health} icon={Monitor} color="bg-cyan-500/15 text-cyan-400" />
                  <MetricBar label="Payment Health" value={clientDetail.metrics?.payment_health} icon={CreditCard} color="bg-emerald-500/15 text-emerald-400" />
                  <MetricBar label="Backup Health" value={clientDetail.metrics?.backup_health} icon={HardDrive} color="bg-purple-500/15 text-purple-400" />
                  <MetricBar label="Security Posture" value={clientDetail.metrics?.security_health} icon={Shield} color="bg-red-500/15 text-red-400" />
                  {clientDetail.metrics?.network_health != null && (
                    <MetricBar label="Network Health" value={clientDetail.metrics.network_health} icon={Wifi} color="bg-indigo-500/15 text-indigo-400" />
                  )}
                  {clientDetail.metrics?.m365_hygiene != null && (
                    <MetricBar label="M365 Hygiene" value={clientDetail.metrics.m365_hygiene} icon={Lock} color="bg-sky-500/15 text-sky-400" />
                  )}
                  {Number.isFinite(clientDetail.metrics?.sentiment) && <MetricBar label="Recorded Sentiment" value={clientDetail.metrics.sentiment} icon={Activity} color="bg-amber-500/15 text-amber-400" />}
                </CardContent>
              </Card>

              {/* Risk / Positive Factors */}
              {(clientDetail.risk_factors?.length > 0 || clientDetail.positive_factors?.length > 0) && (
                <Card>
                  <CardContent className="pt-3 pb-3 space-y-2">
                    {clientDetail.risk_factors?.map((rf, i) => (
                      <div key={`r-${i}`} className="flex items-center gap-2 text-xs">
                        <AlertTriangle className={`w-3 h-3 flex-shrink-0 ${rf.severity === "critical" ? "text-red-400" : "text-amber-400"}`} />
                        <span className="flex-1">{rf.factor}</span>
                        <Badge className={`text-[8px] ${rf.severity === "critical" ? "bg-red-500/20 text-red-400" : "bg-amber-500/20 text-amber-400"}`}>{rf.impact}</Badge>
                      </div>
                    ))}
                    {clientDetail.positive_factors?.map((pf, i) => (
                      <div key={`p-${i}`} className="flex items-center gap-2 text-xs">
                        <Check className="w-3 h-3 flex-shrink-0 text-emerald-400" />
                        <span className="flex-1">{pf.factor}</span>
                        <Badge className="text-[8px] bg-emerald-500/20 text-emerald-400">{pf.impact}</Badge>
                      </div>
                    ))}
                  </CardContent>
                </Card>
              )}

              {/* Key Stats */}
              <Card>
                <CardContent className="pt-3 pb-3">
                  <div className="grid grid-cols-3 gap-2 text-center">
                    {[
                      { label: "Open Tickets", val: clientDetail.details?.open_tickets || 0, color: "text-amber-400" },
                      { label: "Devices Online", val: clientDetail.details?.device_observed ? `${clientDetail.details.online_devices}/${clientDetail.details.devices}` : "—", color: "text-cyan-400" },
                      { label: "Backup Rate", val: Number.isFinite(clientDetail.details?.backup_success_rate) ? `${clientDetail.details.backup_success_rate}%` : "—", color: "text-purple-400" },
                      { label: "Overdue Invoices", val: clientDetail.details?.overdue_invoices || 0, color: "text-red-400" },
                      { label: "Security Alerts", val: clientDetail.details?.security_observed ? clientDetail.details.security_alerts : "—", color: "text-red-400" },
                      { label: "Expiring Contracts", val: clientDetail.details?.expiring_contracts || 0, color: "text-amber-400" },
                    ].map(s => (
                      <div key={s.label} className="p-2 rounded-lg bg-muted/10">
                        <p className={`text-base font-bold ${s.color}`}>{s.val}</p>
                        <p className="text-[9px] text-muted-foreground">{s.label}</p>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </>
          ) : null}
        </div>
      </div>

      {/* Alert Settings Dialog */}
      <Dialog open={settingsDialog} onOpenChange={setSettingsDialog}>
        <DialogContent aria-describedby="alert-config-desc">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2"><Bell className="w-5 h-5 text-amber-400" />Health Alert Settings</DialogTitle>
            <DialogDescription id="alert-config-desc">Configure thresholds and notification rules for client health monitoring</DialogDescription>
          </DialogHeader>
          {alertConfig && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div><Label className="text-xs">Critical Threshold (score below)</Label><Input type="number" value={alertConfig.critical_threshold} onChange={e => setAlertConfig({ ...alertConfig, critical_threshold: parseInt(e.target.value) })} /></div>
                <div><Label className="text-xs">Warning Threshold (score below)</Label><Input type="number" value={alertConfig.warning_threshold} onChange={e => setAlertConfig({ ...alertConfig, warning_threshold: parseInt(e.target.value) })} /></div>
              </div>
              <Separator />
              <div className="space-y-3">
                <div className="flex items-center justify-between"><div><Label className="text-sm">Notify on Score Decline</Label><p className="text-[11px] text-muted-foreground">Alert when any client's health drops by this amount</p></div><Switch checked={alertConfig.notify_on_decline} onCheckedChange={v => setAlertConfig({ ...alertConfig, notify_on_decline: v })} /></div>
                {alertConfig.notify_on_decline && <div><Label className="text-xs">Decline Amount</Label><Input type="number" value={alertConfig.decline_amount} onChange={e => setAlertConfig({ ...alertConfig, decline_amount: parseInt(e.target.value) })} className="max-w-[100px]" /></div>}
                <div className="rounded-lg border border-muted p-3 text-[11px] text-muted-foreground">Ticket creation is intentionally not automated from this preference. Confirmed health findings remain visible here for technician review and ticket creation through the normal service workflow.</div>
              </div>
              <div><Label className="text-xs">Notification Email</Label><Input value={alertConfig.notify_email || ""} onChange={e => setAlertConfig({ ...alertConfig, notify_email: e.target.value })} placeholder="alerts@company.com" /></div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setSettingsDialog(false)}>Cancel</Button>
            <Button onClick={saveAlertConfig} data-testid="save-alert-config"><Check className="w-4 h-4 mr-1" />Save Settings</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

