  const delta = firstVal > 0 ? ((lastVal - firstVal) / firstVal) * 100 : 0;

  return (
    <button
      onClick={onClick}
      data-testid={`client-list-item-${client.id}`}
      className={`w-full text-left flex items-center gap-3 px-4 py-3 border-b border-zinc-800/80 transition-colors
