const DEFAULT_LAYOUT_LG = [
  { i: "live-ticker", x: 0, y: 0,  w: 12, h: 1, minH: 1, minW: 6 },
  { i: "open-tix",    x: 0, y: 1,  w: 6,  h: 7, minH: 5, minW: 4 },
