import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import { 
  MessageSquare,
  Send,
  Terminal,
  FileUp,
  Trash2,
  Monitor,
  User,
  Bot,
  ArrowLeft,
  RefreshCw,
  Loader2,
