                    <td className={`p-2 text-right ${p.cost_change_pct > 5 ? "text-amber-400" : "text-muted-foreground"}`}>{p.cost_change_pct != null ? `${p.cost_change_pct > 0 ? "+" : ""}${p.cost_change_pct}%` : "–"}</td>
