    updated[i] = { ...updated[i], [field]: val };
    onChange({ ...data, devices: updated });
  };
  const addDevice = () => onChange({ ...data, devices: [...devices, { hostname: "", type: "workstation", os: "", ip: "", mac: "", serial: "", manufacturer: "", model: "", location: "" }] });
