                              label: `${ticket.ticket_number || "Ticket"} — ${ticket.title || "Untitled"}`,
                              detail: ticket.status ? `Status: ${ticket.status.replace(/_/g, " ")}` : "Service ticket",
                              searchText: `${ticket.ticket_number || ""} ${ticket.title || ""}`,
