          }} data-testid="save-threshold-btn">
            <Save className="w-4 h-4 mr-2" />Save Threshold Settings
          </Button>
        </CardContent>
      </Card>
      </>)}

      {/* ==================== DISPATCH CALENDAR TAB ==================== */}
      {activeTab === "calendar" && (<>
