                  const res = await axios.post(`${API}/settings/hudu/test`, {}, { headers });
                  if (res.data.success) toast.success(res.data.message);
                  else toast.error(res.data.message);
                } catch (e) { toast.error("Connection test failed"); }
              }} data-testid="test-hudu-btn">
                Test Connection
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Syncro RMM Integration */}
      <Card id="syncro-settings-card" data-testid="syncro-settings-card">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Zap className="w-5 h-5 text-orange-500" />
            <CardTitle>Syncro RMM - Client Import</CardTitle>
          </div>
          <CardDescription>Connect to Syncro to import clients, contacts, and devices</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <SetupGuideCallout title="Prepare a Syncro import key" source="In Syncro, create an API token under Admin → API Tokens and enter only the account subdomain, not the full Syncro URL." steps={["Use a dedicated read-focused import token where the source permissions allow it.", "Validate the subdomain before saving.", "Test before importing, then review client matches to avoid duplicates."]} securityNote="Do not use a technician’s personal token for recurring imports. Revoke the token in Syncro when the integration is retired." />
          <div className="flex items-center gap-2">
            <Badge className={syncro.enabled ? "bg-green-500/20 text-green-400 border-green-500/30" : "bg-red-500/20 text-red-400 border-red-500/30"}>
              {syncro.enabled ? "Connected" : "Not Configured"}
            </Badge>
          </div>
          <div>
            <Label>Syncro Subdomain</Label>
            <Input
              value={syncro.subdomain}
              onChange={(e) => setSyncro({ ...syncro, subdomain: e.target.value })}
              placeholder="your-company"
              data-testid="syncro-subdomain"
            />
            <p className="text-xs text-muted-foreground mt-1">Your Syncro subdomain (e.g., if your URL is https://your-company.syncromsp.com, enter "your-company")</p>
          </div>
          <div>
            <Label>API Key</Label>
            <Input
              type="password"
              value={syncro.api_key}
              onChange={(e) => setSyncro({ ...syncro, api_key: e.target.value })}
              placeholder="Syncro API Key"
              data-testid="syncro-api-key"
            />
            <p className="text-xs text-muted-foreground mt-1">Generate an API key in Syncro under <strong>Admin &gt; API Tokens</strong>.</p>
          </div>
          <div className="flex gap-2">
            <Button onClick={async () => {
              if (!syncro.subdomain || !syncro.api_key) { toast.error("Subdomain and API key required"); return; }
              setSyncroSaving(true);
              try {
                await axios.put(`${API}/syncro/settings`, { subdomain: syncro.subdomain, api_key: syncro.api_key, enabled: true }, { headers });
                toast.success("Syncro settings saved");
                setSyncro({ ...syncro, enabled: true });
              } catch (e) { toast.error(e.response?.data?.detail || "Failed to save"); }
              finally { setSyncroSaving(false); }
            }} data-testid="save-syncro-btn" disabled={syncroSaving}>
              {syncroSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}Save Syncro Settings
            </Button>
            {syncro.enabled && (
              <>
                <Button variant="outline" onClick={async () => {
                  try {
                    const res = await axios.post(`${API}/syncro/test-connection`, {}, { headers });
                    if (res.data.status === "connected") toast.success(res.data.message);
                    else toast.error(res.data.message);
                  } catch (e) { toast.error("Connection test failed"); }
                }} data-testid="test-syncro-btn">
                  Test Connection
                </Button>
                <Button variant="default" onClick={async () => {
                  if (!window.confirm("Import all clients from Syncro? This may take a moment.")) return;
                  try {
                    toast.info("Importing clients from Syncro...");
                    const res = await axios.post(`${API}/syncro/import-clients`, {}, { headers });
                    toast.success(res.data.message);
                  } catch (e) { toast.error(e.response?.data?.detail || "Import failed"); }
                }} data-testid="import-syncro-btn">
                  Import Clients
                </Button>
              </>
            )}
          </div>
        </CardContent>
      </Card>
      </>)}

      {/* === Merged sub-pages (lazy) === */}
      {activeTab === "tickets" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading ticket defaults...</div>}>
          <LazyTicketSettings />
        </Suspense>
      )}
      {activeTab === "ping" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading ping & escalation...</div>}>
          <LazyTicketPingSettings />
        </Suspense>
      )}
      {activeTab === "white-label" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading white label...</div>}>
          <LazyWhiteLabel />
        </Suspense>
      )}
      {activeTab === "channel" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading channel mode...</div>}>
          <LazyChannelMode />
        </Suspense>
      )}
      {activeTab === "tokens" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading API tokens...</div>}>
          <LazyApiTokens />
        </Suspense>
      )}
      {activeTab === "twofa" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading 2FA settings...</div>}>
          <LazySecurity2FA />
        </Suspense>
      )}
      {activeTab === "comms" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading notify channels...</div>}>
          <LazyNotifyChannels />
        </Suspense>
      )}
      {activeTab === "my-settings" && (
        <Suspense fallback={<div className="p-8 text-sm text-muted-foreground"><Loader2 className="w-4 h-4 inline mr-2 animate-spin" />Loading my workspace...</div>}>
          <LazyTechSettings />
        </Suspense>
      )}

      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Users, Edit } from "lucide-react";
import { toast } from "sonner";

const skillLevels = { 0: "None", 1: "Basic", 2: "Intermediate", 3: "Advanced", 4: "Expert" };
const skillColors = { 0: "text-slate-400", 1: "text-blue-400", 2: "text-blue-500", 3: "text-green-500", 4: "text-amber-500" };

export default function SkillsMatrixPage() {
  const { token } = useAuth();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);
  const [editSkills, setEditSkills] = useState({});
  const [editCerts, setEditCerts] = useState("");
  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = () => {
    axios.get(`${API}/skills-matrix`, { headers })
      .then(r => setData(r.data))
      .catch(() => {})
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchData(); }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const startEdit = (tech) => {
    setEditing(tech);
    setEditSkills({ ...tech.skills });
    setEditCerts((tech.certifications || []).join(", "));
  };

  const saveSkills = async () => {
    try {
      await axios.put(`${API}/skills-matrix/${editing.user_id}`, {
        skills: editSkills,
        certifications: editCerts.split(",").map(c => c.trim()).filter(Boolean),
      }, { headers });
      toast.success("Skills updated");
      setEditing(null);
      fetchData();
    } catch { toast.error("Update failed"); }
  };

  if (loading) return <div className="flex justify-center py-20"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" /></div>;
  if (!data) return null;

  return (
    <div className="space-y-6" data-testid="skills-matrix-page">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Technician Skills Matrix</h1>
        <p className="text-muted-foreground text-sm mt-1">Skills inventory with auto-matching for ticket assignment</p>
      </div>

      <Card>
        <CardHeader><CardTitle className="text-base flex items-center gap-2"><Users className="w-4 h-4" />Skills Matrix</CardTitle></CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="sticky left-0 bg-card z-10">Technician</TableHead>
                  {data.all_skills.map(s => <TableHead key={s} className="text-center capitalize text-xs">{s}</TableHead>)}
                  <TableHead>Certs</TableHead>
                  <TableHead className="text-right">Resolved</TableHead>
                  <TableHead></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {data.technicians.map(tech => (
                  <TableRow key={tech.user_id} data-testid={`skills-row-${tech.user_id}`}>
                    <TableCell className="font-medium sticky left-0 bg-card">{tech.name}</TableCell>
                    {data.all_skills.map(s => {
                      const level = tech.skills[s] || 0;
                      return (
                        <TableCell key={s} className="text-center">
                          <span className={`text-xs font-medium ${skillColors[level]}`}>
                            {level > 0 ? `${"*".repeat(level)}` : "-"}
                          </span>
                        </TableCell>
                      );
                    })}
                    <TableCell>
                      {(tech.certifications || []).map((c, i) => (
                        <Badge key={`k-${i}`} variant="outline" className="text-[10px] mr-1">{c}</Badge>
                      ))}
                    </TableCell>
                    <TableCell className="text-right font-mono">{tech.total_resolved}</TableCell>
                    <TableCell>
                      <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => startEdit(tech)} data-testid={`edit-skills-${tech.user_id}`}>
                        <Edit className="w-3 h-3" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="flex items-center gap-2 text-xs"><span className="text-slate-400">-</span> None</div>
        <div className="flex items-center gap-2 text-xs"><span className="text-blue-400">*</span> Basic</div>
        <div className="flex items-center gap-2 text-xs"><span className="text-blue-500">**</span> Intermediate</div>
        <div className="flex items-center gap-2 text-xs"><span className="text-green-500">***</span> Advanced</div>
      </div>

      {editing && (
        <Dialog open={!!editing} onOpenChange={() => setEditing(null)}>
          <DialogContent>
            <DialogHeader><DialogTitle>Edit Skills: {editing.name}</DialogTitle></DialogHeader>
            <div className="space-y-3">
              {data.all_skills.map(s => (
                <div key={s} className="flex items-center justify-between">
                  <span className="capitalize text-sm">{s}</span>
                  <div className="flex gap-1">
                    {[0,1,2,3,4].map(l => (
                      <Button key={l} variant={editSkills[s] === l ? "default" : "outline"} size="sm" className="h-7 w-7 text-xs p-0"
                        onClick={() => setEditSkills(p => ({ ...p, [s]: l }))} data-testid={`skill-${s}-level-${l}`}>
                        {l}
                      </Button>
                    ))}
                  </div>
                </div>
              ))}
              <div>
                <label className="text-sm font-medium">Certifications (comma-separated)</label>
                <Input value={editCerts} onChange={e => setEditCerts(e.target.value)} placeholder="CCNA, Azure, CompTIA..." data-testid="certs-input" />
              </div>
              <Button onClick={saveSkills} className="w-full" data-testid="save-skills">Save Skills</Button>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { toast } from "sonner";
import {
  Loader2, AlertTriangle, Activity, Search,
  Ticket, Lock, CheckCircle, XCircle, Clock, Eye, Wrench, RefreshCw, Zap
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";

const SEV = {
  critical: { class: "bg-red-500/20 text-red-400 border-red-500/30", dot: "bg-red-500" },
  high: { class: "bg-orange-500/20 text-orange-400 border-orange-500/30", dot: "bg-orange-500" },
  medium: { class: "bg-amber-500/20 text-amber-400 border-amber-500/30", dot: "bg-amber-500" },
  low: { class: "bg-blue-500/20 text-blue-400 border-blue-500/30", dot: "bg-blue-500" },
};

const STATUS_CONFIG = {
  new: { label: "New", class: "bg-red-500/20 text-red-400", icon: AlertTriangle },
  investigating: { label: "Investigating", class: "bg-amber-500/20 text-amber-400", icon: Eye },
  remediated: { label: "Remediated", class: "bg-green-500/20 text-green-400", icon: CheckCircle },
  closed: { label: "Closed", class: "bg-gray-500/20 text-gray-400", icon: XCircle },
};

export default function SocFeedPage() {
  const { token } = useAuth();
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [selectedAlert, setSelectedAlert] = useState(null);
  const [ticketDialog, setTicketDialog] = useState(false);
  const [ticketForm, setTicketForm] = useState({ title: "", description: "", priority: "high" });
  const [remediateDialog, setRemediateDialog] = useState(false);
  const [remediateNotes, setRemediateNotes] = useState("");
  const [actionLoading, setActionLoading] = useState(null);
  const headers = { Authorization: `Bearer ${token}` };

  const fetchAlerts = useCallback(async () => {
    setLoading(true);
    try {
      const [socRes, huntRes, huntStatusRes] = await Promise.all([
        axios.get(`${API}/soc/alerts`, { headers }),
        axios.get(`${API}/huntress/incident-reports?limit=500`, { headers }).catch(() => ({ data: null })),
        axios.get(`${API}/huntress/status`, { headers }).catch(() => ({ data: { configured: false } })),
      ]);
      const socList = socRes.data || [];
      if (huntStatusRes.data?.configured && Array.isArray(huntRes.data) && huntRes.data.length > 0) {
        // Normalise Huntress incidents into the SOC alert shape
        const huntAlerts = huntRes.data.map((i) => ({
          id: `hunt-${i.id}`,
          title: i.summary || i.title || "Huntress incident",
          description: i.description || i.summary || "",
          severity: (i.severity || "low").toLowerCase(),
          status: ["resolved", "closed"].includes((i.status || "").toLowerCase()) ? "remediated" : "new",
          hostname: i.agent_hostname || i.hostname || "—",
          organization: i.organization_name || i.organization_id || "—",
          created_at: i.detected_at || i.created_at,
          source: "huntress",
          _raw_id: i.id,
        }));
        setAlerts([...huntAlerts, ...socList]);
      } else {
        setAlerts(socList);
      }
    } catch { toast.error("Failed to load alerts"); }
    finally { setLoading(false); }
  }, [token]);

  useEffect(() => { fetchAlerts(); }, [fetchAlerts]);

  const handleAcknowledge = async (alertId) => {
    setActionLoading(alertId);
    try {
      await axios.post(`${API}/soc/alerts/${alertId}/acknowledge`, {}, { headers });
      toast.success("Alert acknowledged");
      fetchAlerts();
    } catch { toast.error("Failed"); }
    finally { setActionLoading(null); }
  };

  const handleCreateTicket = async () => {
    if (!selectedAlert) return;
    try {
      const res = await axios.post(`${API}/soc/alerts/${selectedAlert.id}/create-ticket`, ticketForm, { headers });
      toast.success(`Ticket ${res.data.ticket_number} created`);
      setTicketDialog(false);
      fetchAlerts();
    } catch (e) { toast.error(e.response?.data?.detail || "Failed"); }
  };

  const handleIsolate = async (alert) => {
    if (alert.source !== "huntress") {
      toast.info("Endpoint isolation requires a configured EDR integration. No isolation command was sent.");
      return;
    }
    setActionLoading(alert.id);
    try {
      const res = await axios.post(`${API}/huntress/agents/${alert._raw_id || alert.hostname}/isolate`, {}, { headers });
      if (res.data?.success) toast.success(`${alert.hostname} isolated via Huntress`);
      else toast.error(`Huntress rejected: ${res.data?.message || "not supported"}`, { duration: 6000 });
      fetchAlerts();
    } catch (e) { toast.error(e.response?.data?.detail || "Failed"); }
    finally { setActionLoading(null); }
  };

  const handleRemediate = async () => {
    if (!selectedAlert) return;
    try {
      await axios.post(`${API}/soc/alerts/${selectedAlert.id}/remediate`, { notes: remediateNotes }, { headers });
      toast.success("Alert remediated");
      setRemediateDialog(false);
      fetchAlerts();
    } catch { toast.error("Failed"); }
  };

  const handleClose = async (alertId) => {
    try {
      await axios.post(`${API}/soc/alerts/${alertId}/close`, { reason: "Resolved" }, { headers });
      toast.success("Alert closed");
      fetchAlerts();
    } catch { toast.error("Failed"); }
  };

  const filtered = alerts
    .filter(a => sevFilter === "all" || a.severity === sevFilter)
    .filter(a => statusFilter === "all" || a.status === statusFilter)
    .filter(a => !search || a.title?.toLowerCase().includes(search.toLowerCase()) || a.hostname?.toLowerCase().includes(search.toLowerCase()));

  const counts = {
    critical: alerts.filter(a => a.severity === "critical" && a.status !== "closed").length,
    high: alerts.filter(a => a.severity === "high" && a.status !== "closed").length,
    open: alerts.filter(a => ["new", "investigating"].includes(a.status)).length,
  };

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin" /></div>;

  return (
    <div className="space-y-6" data-testid="soc-feed">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">SOC Alert Feed</h1>
          <p className="text-muted-foreground">{alerts.length} persisted alerts{alerts.some(alert => alert.source === "huntress") ? " and connected Huntress incidents" : ""}</p>
        </div>
        <Button variant="outline" onClick={fetchAlerts}><RefreshCw className="w-4 h-4 mr-1" />Refresh</Button>
      </div>

      {/* Summary Bar */}
      <div className="flex gap-3">
        <Card className="flex-1 border-red-500/20"><CardContent className="pt-3 pb-2 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" /><span className="text-xs text-muted-foreground">Critical</span><span className="text-lg font-bold text-red-400 ml-auto">{counts.critical}</span></CardContent></Card>
        <Card className="flex-1 border-orange-500/20"><CardContent className="pt-3 pb-2 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-orange-500" /><span className="text-xs text-muted-foreground">High</span><span className="text-lg font-bold text-orange-400 ml-auto">{counts.high}</span></CardContent></Card>
        <Card className="flex-1"><CardContent className="pt-3 pb-2 flex items-center gap-2"><Activity className="w-4 h-4 text-amber-400" /><span className="text-xs text-muted-foreground">Open</span><span className="text-lg font-bold ml-auto">{counts.open}</span></CardContent></Card>
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <div className="relative flex-1 max-w-sm"><Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" /><Input className="pl-9" placeholder="Search alerts..." value={search} onChange={e => setSearch(e.target.value)} data-testid="alert-search" /></div>
        <Select value={sevFilter} onValueChange={setSevFilter}><SelectTrigger className="w-[130px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All Severity</SelectItem><SelectItem value="critical">Critical</SelectItem><SelectItem value="high">High</SelectItem><SelectItem value="medium">Medium</SelectItem><SelectItem value="low">Low</SelectItem></SelectContent></Select>
        <Select value={statusFilter} onValueChange={setStatusFilter}><SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All Status</SelectItem><SelectItem value="new">New</SelectItem><SelectItem value="investigating">Investigating</SelectItem><SelectItem value="remediated">Remediated</SelectItem><SelectItem value="closed">Closed</SelectItem></SelectContent></Select>
      </div>

      {/* Alert List */}
      <div className="space-y-2">
        {filtered.length === 0 ? (
          <Card><CardContent className="py-12 text-center text-muted-foreground">No alerts match your filters</CardContent></Card>
        ) : filtered.map(alert => {
          const StatusIcon = STATUS_CONFIG[alert.status]?.icon || Clock;
          return (
            <Card key={alert.id} className={`transition-all hover:bg-muted/30 ${alert.severity === "critical" && alert.status === "new" ? "border-red-500/30 bg-red-500/5" : ""}`} data-testid={`alert-${alert.id}`}>
              <CardContent className="py-3 px-4">
                <div className="flex items-start gap-3">
                  <div className={`w-2 h-2 rounded-full mt-2 flex-shrink-0 ${SEV[alert.severity]?.dot}`} />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium text-sm">{alert.title}</span>
                      <Badge className={SEV[alert.severity]?.class + " text-[10px]"}>{alert.severity}</Badge>
                      <Badge className={STATUS_CONFIG[alert.status]?.class + " text-[10px]"}><StatusIcon className="w-3 h-3 mr-1" />{STATUS_CONFIG[alert.status]?.label}</Badge>
                      {alert.source && <Badge variant="outline" className="text-[10px] text-muted-foreground">{alert.source === "huntress" ? "Huntress" : "NexusMSP"}</Badge>}
                      {alert.mitre_attack && <Badge variant="outline" className="text-[10px] font-mono">{alert.mitre_attack}</Badge>}
                      {alert.ticket_number && <Badge variant="outline" className="text-[10px] text-green-400 border-green-500/30"><Ticket className="w-3 h-3 mr-1" />{alert.ticket_number}</Badge>}
                    </div>
                    <div className="flex items-center gap-4 mt-1 text-[11px] text-muted-foreground">
                      <span className="font-mono">{alert.hostname}</span>
                      <span>{alert.organization}</span>
                      <span>{alert.created_at ? formatDistanceToNow(new Date(alert.created_at), { addSuffix: true }) : ""}</span>
                      {alert.assigned_to && <span className="text-blue-400">Assigned: {alert.assigned_to}</span>}
                    </div>
                  </div>
                  <div className="flex gap-1 flex-shrink-0">
                    {alert.status === "new" && (
                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => handleAcknowledge(alert.id)} disabled={actionLoading === alert.id} data-testid={`ack-${alert.id}`}>
                        <Eye className="w-3 h-3 mr-1" />Ack
                      </Button>
                    )}
                    {!alert.ticket_id && !alert.ticket_number && (
                      <Button size="sm" variant="outline" className="h-7 text-xs text-blue-400 border-blue-500/30" onClick={() => {
                        setSelectedAlert(alert);
                        setTicketForm({ title: `[SOC] ${alert.title}`, description: `${alert.description || ""}\n\nHost: ${alert.hostname}\nSeverity: ${alert.severity}\nMITRE: ${alert.mitre_attack || "N/A"}`, priority: alert.severity === "critical" ? "critical" : "high" });
                        setTicketDialog(true);
                      }} data-testid={`create-ticket-${alert.id}`}>
                        <Ticket className="w-3 h-3 mr-1" />Ticket
                      </Button>
                    )}
                    {alert.source === "huntress" && ["new", "investigating"].includes(alert.status) && (
                      <Button size="sm" variant="outline" className="h-7 text-xs text-purple-400 border-purple-500/30" onClick={() => handleIsolate(alert)} disabled={actionLoading === alert.id} data-testid={`isolate-${alert.id}`}>
                        <Lock className="w-3 h-3 mr-1" />Isolate
                      </Button>
                    )}
                    {alert.status === "investigating" && (
                      <Button size="sm" variant="outline" className="h-7 text-xs text-green-400 border-green-500/30" onClick={() => { setSelectedAlert(alert); setRemediateNotes(""); setRemediateDialog(true); }} data-testid={`remediate-${alert.id}`}>
                        <Wrench className="w-3 h-3 mr-1" />Fix
                      </Button>
                    )}
                    {alert.status === "remediated" && (
                      <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => handleClose(alert.id)} data-testid={`close-${alert.id}`}>
                        <CheckCircle className="w-3 h-3 mr-1" />Close
                      </Button>
                    )}
                  </div>
                </div>
                {alert.remediation_steps && alert.status !== "closed" && (
                  <div className="mt-2 ml-5 p-2 rounded bg-muted/20 border border-dashed">
                    <p className="text-[10px] font-semibold text-muted-foreground mb-1">Recommended Actions:</p>
                    <ul className="text-[11px] space-y-0.5 text-muted-foreground">{(alert.remediation_steps || []).map((s, i) => <li key={`k-${i}`} className="flex items-start gap-1"><Zap className="w-3 h-3 mt-0.5 text-amber-400 flex-shrink-0" />{s}</li>)}</ul>
                  </div>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Create Ticket Dialog */}
      <Dialog open={ticketDialog} onOpenChange={setTicketDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle className="flex items-center gap-2"><Ticket className="w-5 h-5 text-blue-400" />Create Ticket from Alert</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div><Label>Title</Label><Input value={ticketForm.title} onChange={e => setTicketForm({ ...ticketForm, title: e.target.value })} data-testid="ticket-title" /></div>
            <div><Label>Description</Label><Textarea value={ticketForm.description} onChange={e => setTicketForm({ ...ticketForm, description: e.target.value })} rows={4} /></div>
            <div><Label>Priority</Label>
              <Select value={ticketForm.priority} onValueChange={v => setTicketForm({ ...ticketForm, priority: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent><SelectItem value="critical">Critical</SelectItem><SelectItem value="high">High</SelectItem><SelectItem value="medium">Medium</SelectItem><SelectItem value="low">Low</SelectItem></SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter><Button onClick={handleCreateTicket} className="bg-blue-600 hover:bg-blue-700" data-testid="confirm-create-ticket"><Ticket className="w-4 h-4 mr-1" />Create Ticket</Button></DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Remediate Dialog */}
      <Dialog open={remediateDialog} onOpenChange={setRemediateDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader><DialogTitle className="flex items-center gap-2"><Wrench className="w-5 h-5 text-green-400" />Remediate Alert</DialogTitle></DialogHeader>
          <div className="space-y-3">
            {selectedAlert && <div className="p-3 rounded-lg bg-muted/30 border text-sm"><p className="font-medium">{selectedAlert.title}</p><p className="text-xs text-muted-foreground mt-1">{selectedAlert.hostname} - {selectedAlert.severity}</p></div>}
            <div><Label>Remediation Notes</Label><Textarea value={remediateNotes} onChange={e => setRemediateNotes(e.target.value)} rows={3} placeholder="Describe actions taken..." /></div>
          </div>
          <DialogFooter><Button onClick={handleRemediate} className="bg-green-600 hover:bg-green-700" data-testid="confirm-remediate"><CheckCircle className="w-4 h-4 mr-1" />Mark Remediated</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Separator } from "@/components/ui/separator";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import {
  Loader2, Settings, Zap, MessageSquare, Clock, DollarSign, CheckCircle,
  AlertTriangle, RefreshCw
} from "lucide-react";

export default function SocRealtimePage() {
  const { token } = useAuth();
  const [settings, setSettings] = useState(null);
  const [recon, setRecon] = useState(null);
  const [loading, setLoading] = useState(true);
  const [thankYouResult, setThankYouResult] = useState(null);
  const [staleResult, setStaleResult] = useState(null);
  const [actionLoading, setActionLoading] = useState(null);
  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [settingsRes, reconRes] = await Promise.all([
        axios.get(`${API}/automation/settings`, { headers }),
        axios.get(`${API}/automation/billing-recon`, { headers }),
      ]);
      setSettings(settingsRes.data);
      setRecon(reconRes.data);
    } catch { toast.error("Failed to load"); }
    finally { setLoading(false); }
  }, [token]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const saveSettings = async () => {
    try {
      await axios.put(`${API}/automation/settings`, settings, { headers });
      toast.success("Settings saved");
    } catch { toast.error("Failed to save"); }
  };

  const runThankYou = async () => {
    setActionLoading("thank_you");
    try {
      const res = await axios.post(`${API}/automation/check-thank-you`, {}, { headers });
      setThankYouResult(res.data);
      toast.success(res.data.message);
    } catch { toast.error("Failed"); }
    finally { setActionLoading(null); }
  };

  const runStaleCheck = async () => {
    setActionLoading("stale");
    try {
      const res = await axios.post(`${API}/automation/check-stale-tickets`, {}, { headers });
      setStaleResult(res.data);
      toast.success(res.data.message);
    } catch { toast.error("Failed"); }
    finally { setActionLoading(null); }
  };

  if (loading || !settings) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin" /></div>;

  const reconSummary = recon?.summary || {};

  return (
    <div className="space-y-6" data-testid="smart-automation">
      <div className="flex items-center justify-between">
        <div><h1 className="text-3xl font-bold tracking-tight">Smart Automation</h1><p className="text-muted-foreground">Intelligent ticket management & billing reconciliation</p></div>
      </div>

      <div className="grid grid-cols-12 gap-6">
        {/* Automation Settings */}
        <div className="col-span-5 space-y-4">
          <Card data-testid="automation-settings">
            <CardHeader><CardTitle className="text-sm flex items-center gap-2"><Settings className="w-4 h-4" />Automation Settings</CardTitle></CardHeader>
            <CardContent className="space-y-5">
              {/* Thank You Detection */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <div><Label className="text-sm font-semibold flex items-center gap-2"><MessageSquare className="w-4 h-4 text-green-400" />Thank You Detection</Label><p className="text-xs text-muted-foreground mt-0.5">Auto-close tickets with thank-you replies</p></div>
                  <Switch checked={settings.thank_you_detection} onCheckedChange={v => setSettings({ ...settings, thank_you_detection: v })} data-testid="toggle-thank-you" />
                </div>
                <div><Label className="text-xs">Keywords (comma-separated)</Label><Input value={(settings.thank_you_keywords || []).join(", ")} onChange={e => setSettings({ ...settings, thank_you_keywords: e.target.value.split(",").map(s => s.trim()).filter(Boolean) })} className="text-sm" data-testid="thank-you-keywords" /></div>
                <Button size="sm" onClick={runThankYou} disabled={actionLoading === "thank_you"} data-testid="run-thank-you">
                  {actionLoading === "thank_you" ? <Loader2 className="w-3 h-3 mr-1 animate-spin" /> : <Zap className="w-3 h-3 mr-1" />}Run Now
                </Button>
                {thankYouResult && <div className="p-2 rounded bg-green-500/10 border border-green-500/20 text-xs text-green-400">Scanned {thankYouResult.scanned} tickets, auto-closed {thankYouResult.closed}</div>}
              </div>
              <Separator />
              {/* Stale Ticket Reminders */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <div><Label className="text-sm font-semibold flex items-center gap-2"><Clock className="w-4 h-4 text-amber-400" />Stale Ticket Reminders</Label><p className="text-xs text-muted-foreground mt-0.5">Auto-ping clients on inactive tickets</p></div>
                  <Switch checked={settings.stale_ticket_enabled} onCheckedChange={v => setSettings({ ...settings, stale_ticket_enabled: v })} data-testid="toggle-stale" />
                </div>
                <div className="flex items-center gap-2"><Label className="text-xs whitespace-nowrap">Stale after</Label><Input type="number" min="1" max="30" value={settings.stale_ticket_days} onChange={e => setSettings({ ...settings, stale_ticket_days: parseInt(e.target.value) || 3 })} className="w-16 text-sm" /><span className="text-xs text-muted-foreground">days</span></div>
                <Button size="sm" onClick={runStaleCheck} disabled={actionLoading === "stale"} data-testid="run-stale-check">
                  {actionLoading === "stale" ? <Loader2 className="w-3 h-3 mr-1 animate-spin" /> : <RefreshCw className="w-3 h-3 mr-1" />}Check Now
                </Button>
                {staleResult && <div className="p-2 rounded bg-amber-500/10 border border-amber-500/20 text-xs text-amber-400">Found {staleResult.stale_count} stale tickets, pinged {staleResult.pinged}</div>}
              </div>
              <Separator />
              <Button onClick={saveSettings} className="w-full" data-testid="save-automation-settings">Save Settings</Button>
            </CardContent>
          </Card>
        </div>

        {/* Billing Reconciliation */}
        <div className="col-span-7 space-y-4">
          <Card data-testid="billing-recon">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm flex items-center gap-2"><DollarSign className="w-4 h-4 text-green-400" />Billing Reconciliation</CardTitle>
                <Button variant="outline" size="sm" onClick={fetchData}><RefreshCw className="w-3 h-3 mr-1" />Refresh</Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-4 gap-3">
                <div className="p-2 rounded-lg bg-muted/20 text-center"><p className="text-[10px] text-muted-foreground">Clients</p><p className="text-lg font-bold">{reconSummary.total_clients || 0}</p></div>
                <div className="p-2 rounded-lg bg-green-500/10 text-center"><p className="text-[10px] text-muted-foreground">Matched</p><p className="text-lg font-bold text-green-400">{reconSummary.matched || 0}</p></div>
                <div className="p-2 rounded-lg bg-amber-500/10 text-center"><p className="text-[10px] text-muted-foreground">Over</p><p className="text-lg font-bold text-amber-400">{reconSummary.over_provisioned || 0}</p></div>
                <div className="p-2 rounded-lg bg-red-500/10 text-center"><p className="text-[10px] text-muted-foreground">Under</p><p className="text-lg font-bold text-red-400">{reconSummary.under_provisioned || 0}</p></div>
              </div>
              {(reconSummary.potential_revenue_loss || 0) > 0 && (
                <div className="p-3 rounded-lg bg-red-500/10 border border-red-500/20 flex items-center gap-2">
                  <AlertTriangle className="w-5 h-5 text-red-400" />
                  <div><p className="text-sm font-medium text-red-400">Potential Revenue Loss</p><p className="text-xs text-muted-foreground">${reconSummary.potential_revenue_loss} from {reconSummary.total_over_agents} unbilled agents</p></div>
                </div>
              )}
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-0">
              <Table>
                <TableHeader><TableRow><TableHead>Client</TableHead><TableHead className="text-right">Contracted</TableHead><TableHead className="text-right">Actual</TableHead><TableHead className="text-right">Diff</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Impact</TableHead></TableRow></TableHeader>
                <TableBody>
                  {(recon?.reconciliation || []).length === 0 ? <TableRow><TableCell colSpan={6} className="text-center py-6 text-muted-foreground text-sm">No reconciliation data</TableCell></TableRow> :
                  (recon?.reconciliation || []).map((r, i) => (
                    <TableRow key={`k-${i}`} className={r.status === "over" ? "bg-amber-500/5" : r.status === "under" ? "bg-red-500/5" : ""} data-testid={`recon-${i}`}>
                      <TableCell className="font-medium text-sm">{r.client_name}</TableCell>
                      <TableCell className="text-right font-mono">{r.contracted_seats}</TableCell>
                      <TableCell className="text-right font-mono">{r.actual_agents}</TableCell>
                      <TableCell className="text-right font-mono font-bold">
                        <span className={r.difference > 0 ? "text-amber-400" : r.difference < 0 ? "text-red-400" : "text-green-400"}>
                          {r.difference > 0 ? "+" : ""}{r.difference}
                        </span>
                      </TableCell>
                      <TableCell>
                        <Badge className={`text-[10px] ${r.status === "match" ? "bg-green-500/20 text-green-400" : r.status === "over" ? "bg-amber-500/20 text-amber-400" : "bg-red-500/20 text-red-400"}`}>
                          {r.status === "match" ? <CheckCircle className="w-3 h-3 mr-1" /> : <AlertTriangle className="w-3 h-3 mr-1" />}
                          {r.status}
                        </Badge>
                      </TableCell>
                      <TableCell className={`text-right font-mono text-xs ${r.revenue_impact > 0 ? "text-amber-400" : r.revenue_impact < 0 ? "text-green-400" : ""}`}>${r.revenue_impact.toFixed(2)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import {
  Plus, Search, Loader2, ClipboardCheck, ArrowLeft,
  CheckCircle, AlertTriangle, Scan, RefreshCw,
  TrendingDown, TrendingUp, DollarSign, ChevronRight,
  History, Trash2
} from "lucide-react";
import { format } from "date-fns";
import HeroTile from "@/components/HeroTile";

const STATUS_COLORS = {
  in_progress: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  completed: "bg-green-500/20 text-green-400 border-green-500/30",
};

export default function StocktakePage() {
  const { token } = useAuth();
  const [sessions, setSessions] = useState([]);
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("sessions");
  const [newDialog, setNewDialog] = useState(false);
  const [newForm, setNewForm] = useState({ name: "", description: "", location: "All Locations", category_filter: "" });
  const [viewSession, setViewSession] = useState(null);
  const [auditLog, setAuditLog] = useState([]);
  const [countSearch, setCountSearch] = useState("");
  const [scannerInput, setScannerInput] = useState("");
  const [finalizeDialog, setFinalizeDialog] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const scanRef = useRef(null);

  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [sesRes, repRes] = await Promise.all([
        axios.get(`${API}/stocktake/sessions`, { headers }),
        axios.get(`${API}/stocktake/reports/summary`, { headers }),
      ]);
      setSessions(sesRes.data);
      setReport(repRes.data);
    } catch { toast.error("Failed to load stocktake data"); }
    finally { setLoading(false); }
  }, [token]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const fetchSession = async (id) => {
    try {
      const [sRes, aRes] = await Promise.all([
        axios.get(`${API}/stocktake/sessions/${id}`, { headers }),
        axios.get(`${API}/stocktake/sessions/${id}/audit-log`, { headers }),
      ]);
      setViewSession(sRes.data);
      setAuditLog(aRes.data);
    } catch { toast.error("Failed to load session"); }
  };

  const handleCreateSession = async () => {
    if (!newForm.name.trim()) { toast.error("Give this stocktake a session name"); return; }
    try {
      const res = await axios.post(`${API}/stocktake/sessions`, newForm, { headers });
      toast.success(`Stocktake ${res.data.session_number} created with ${res.data.total_items} items`);
      setNewDialog(false);
      setNewForm({ name: "", description: "", location: "All Locations", category_filter: "" });
      fetchData();
      fetchSession(res.data.id);
    } catch (e) { toast.error(e.response?.data?.detail || "Failed to create session"); }
  };

  const handleCount = async (item, qty) => {
    if (!viewSession) return;
    const safeQty = Math.max(0, Number.isFinite(Number(qty)) ? Math.floor(Number(qty)) : 0);
    try {
      await axios.put(`${API}/stocktake/sessions/${viewSession.id}/count`, {
        product_id: item.product_id, counted_qty: safeQty, product_name: item.product_name
      }, { headers });
      fetchSession(viewSession.id);
    } catch (e) { toast.error(e.response?.data?.detail || "Failed to update count"); }
  };

  const handleScannerSubmit = (e) => {
    e.preventDefault();
    if (!scannerInput.trim() || !viewSession) return;
    const item = viewSession.items.find(i =>
      i.barcode === scannerInput.trim() || i.sku === scannerInput.trim()
    );
    if (item) {
      const current = item.counted_qty ?? 0;
      handleCount(item, current + 1);
      toast.success(`Scanned: ${item.product_name} (now ${current + 1})`);
    } else {
      toast.error(`No product found for barcode: ${scannerInput}`);
    }
    setScannerInput("");
    scanRef.current?.focus();
  };

  const handleFinalize = async () => {
    if (!viewSession) return;
    try {
      const res = await axios.put(`${API}/stocktake/sessions/${viewSession.id}/finalize`, { apply_adjustments: true }, { headers });
      toast.success(`Stocktake finalized. ${res.data.adjustments_made} adjustments applied.`);
      fetchSession(viewSession.id);
      fetchData();
      setFinalizeDialog(false);
    } catch (e) { toast.error(e.response?.data?.detail || "Failed to finalize"); }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`${API}/stocktake/sessions/${id}`, { headers });
      toast.success("Session deleted");
      if (viewSession?.id === id) setViewSession(null);
      fetchData();
      setDeleteTarget(null);
    } catch { toast.error("Failed to delete"); }
  };

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin" /></div>;

  const finalizeConfirmation = (
    <AlertDialog open={finalizeDialog} onOpenChange={setFinalizeDialog}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Finalize this stocktake?</AlertDialogTitle>
          <AlertDialogDescription>
            This will apply the counted quantities as inventory adjustments. Uncounted products keep their existing stock level.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Keep Counting</AlertDialogCancel>
          <AlertDialogAction className="bg-green-600 text-white hover:bg-green-700" onClick={handleFinalize} data-testid="confirm-finalize-stocktake">Finalize & Apply Adjustments</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );

  const deleteConfirmation = (
    <AlertDialog open={Boolean(deleteTarget)} onOpenChange={open => !open && setDeleteTarget(null)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete {deleteTarget?.session_number}?</AlertDialogTitle>
          <AlertDialogDescription>This removes the in-progress count and its audit trail. Completed stocktakes remain as inventory history.</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Keep Session</AlertDialogCancel>
          <AlertDialogAction className="bg-destructive text-destructive-foreground hover:bg-destructive/90" onClick={() => deleteTarget && handleDelete(deleteTarget.id)} data-testid="confirm-delete-stocktake">Delete Session</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );

  // ========== SESSION DETAIL VIEW ==========
  if (viewSession) {
    const s = viewSession;
    const progressPct = s.total_items > 0 ? Math.round((s.counted_items / s.total_items) * 100) : 0;
    const filteredItems = s.items?.filter(i =>
      !countSearch || i.product_name?.toLowerCase().includes(countSearch.toLowerCase()) ||
      i.sku?.toLowerCase().includes(countSearch.toLowerCase()) ||
      i.barcode?.toLowerCase().includes(countSearch.toLowerCase())
    ) || [];
    const pendingItems = filteredItems.filter(i => i.status === "pending");
    const countedItems = filteredItems.filter(i => i.status === "counted");
    const varianceItems = filteredItems.filter(i => i.variance && i.variance !== 0);

    return (
      <div className="space-y-6" data-testid="stocktake-detail">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => setViewSession(null)} data-testid="back-to-stocktake">
            <ArrowLeft className="w-4 h-4 mr-1" />Back to Stocktakes
          </Button>
          <ChevronRight className="w-4 h-4 text-muted-foreground" />
          <span className="font-semibold">{s.session_number}</span>
          <Badge className={STATUS_COLORS[s.status]}>{s.status === "in_progress" ? "In Progress" : "Completed"}</Badge>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          <HeroTile label="Count progress" value={`${progressPct}%`} icon={ClipboardCheck} glow="cyan" animated={false} />
          <HeroTile label="Counted items" value={`${s.counted_items} / ${s.total_items}`} icon={CheckCircle} glow="emerald" animated={false} />
          <HeroTile label="Variances" value={s.variance_count || 0} icon={AlertTriangle} glow={s.variance_count > 0 ? "amber" : "emerald"} animated={false} />
          <HeroTile label="Stock loss" value={`$${(s.stock_loss_value || 0).toFixed(2)}`} icon={TrendingDown} glow="rose" animated={false} />
          <HeroTile label="Stock gain" value={`$${(s.stock_gain_value || 0).toFixed(2)}`} icon={TrendingUp} glow="emerald" animated={false} />
        </div>

        {/* Barcode Scanner Strip */}
        {s.status === "in_progress" && (
          <Card className="border-cyan-500/30 bg-cyan-500/5">
            <CardContent className="py-3 flex items-center gap-4">
              <div className="w-10 h-10 rounded-lg bg-cyan-500/20 flex items-center justify-center flex-shrink-0">
                <Scan className="w-5 h-5 text-cyan-400 animate-pulse" />
              </div>
              <form onSubmit={handleScannerSubmit} className="flex-1 flex gap-2">
                <Input ref={scanRef} value={scannerInput} onChange={e => setScannerInput(e.target.value)}
                  placeholder="Scan barcode or type SKU... (auto-increments count)" className="font-mono"
                  data-testid="stocktake-scanner-input" autoFocus />
                <Button type="submit" data-testid="stocktake-scan-btn">Scan</Button>
              </form>
              <p className="text-xs text-muted-foreground flex-shrink-0">Bluetooth / USB scanner ready</p>
            </CardContent>
          </Card>
        )}

        {/* Search + Actions */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input className="pl-9" placeholder="Search items..." value={countSearch} onChange={e => setCountSearch(e.target.value)} />
          </div>
          <Badge variant="outline">{pendingItems.length} pending</Badge>
          <Badge variant="outline" className="text-green-400">{countedItems.length} counted</Badge>
          {varianceItems.length > 0 && <Badge variant="outline" className="text-amber-400">{varianceItems.length} variances</Badge>}
          <div className="flex-1" />
          {s.status === "in_progress" && (
            <Button onClick={() => setFinalizeDialog(true)} className="bg-green-600 hover:bg-green-700" data-testid="finalize-stocktake">
              <CheckCircle className="w-4 h-4 mr-1" />Finalize & Adjust Stock
            </Button>
          )}
        </div>

        {/* Items Table */}
        <Card>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Product</TableHead>
                  <TableHead className="text-right">Expected</TableHead>
                  <TableHead className="text-right">Counted</TableHead>
                  <TableHead className="text-right">Variance</TableHead>
                  <TableHead className="text-right">Loss/Gain ($)</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Counted By</TableHead>
                  {s.status === "in_progress" && <TableHead className="text-right">Count</TableHead>}
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredItems.map(item => {
                  const variance = item.variance ?? null;
                  const isLoss = variance !== null && variance < 0;
                  const isGain = variance !== null && variance > 0;
                  const varValue = variance !== null ? Math.abs(variance) * item.cost_price : 0;
                  return (
                    <TableRow key={item.product_id} className={isLoss ? "bg-red-500/5" : isGain ? "bg-green-500/5" : ""} data-testid={`stocktake-item-${item.product_id}`}>
                      <TableCell>
                        <div>
                          <p className="font-medium text-sm">{item.product_name}</p>
                          <p className="text-xs text-muted-foreground font-mono">{item.sku || item.barcode || "-"}</p>
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-mono">{item.expected_qty}</TableCell>
                      <TableCell className="text-right font-mono font-bold">
                        {item.counted_qty !== null ? item.counted_qty : <span className="text-muted-foreground">-</span>}
                      </TableCell>
                      <TableCell className="text-right">
                        {variance !== null ? (
                          <span className={`font-mono font-bold ${isLoss ? "text-red-400" : isGain ? "text-green-400" : "text-muted-foreground"}`}>
                            {isGain ? "+" : ""}{variance}
                          </span>
                        ) : <span className="text-muted-foreground">-</span>}
                      </TableCell>
                      <TableCell className="text-right">
                        {variance !== null && variance !== 0 ? (
                          <span className={`font-mono text-sm ${isLoss ? "text-red-400" : "text-green-400"}`}>
                            {isLoss ? "-" : "+"}${varValue.toFixed(2)}
                          </span>
                        ) : <span className="text-muted-foreground">-</span>}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline" className={`text-xs ${item.status === "counted" ? "text-green-400 border-green-500/30" : "text-muted-foreground"}`}>
                          {item.status === "counted" ? <CheckCircle className="w-3 h-3 mr-1" /> : null}
                          {item.status}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">{item.counted_by || "-"}</TableCell>
                      {s.status === "in_progress" && (
                        <TableCell className="text-right">
                          <div className="flex items-center gap-1 justify-end">
                            <Input type="number" min="0" className="w-20 h-8 text-sm font-mono text-right"
                              value={item.counted_qty ?? ""}
                              onBlur={e => { const v = parseInt(e.target.value); if (!isNaN(v)) handleCount(item, v); }}
                              onKeyDown={e => { if (e.key === "Enter") { const v = parseInt(e.target.value); if (!isNaN(v)) handleCount(item, v); } }}
                              data-testid={`count-input-${item.product_id}`} />
                          </div>
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })}
                {filteredItems.length === 0 && (
                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">No items match your search</TableCell></TableRow>
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        {/* Audit Log */}
        {auditLog.length > 0 && (
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><History className="w-4 h-4" />Audit Trail ({auditLog.length})</CardTitle></CardHeader>
            <CardContent className="p-0 max-h-48 overflow-y-auto">
              <Table>
                <TableBody>
                  {auditLog.map(l => (
                    <TableRow key={l.id}>
                      <TableCell className="text-xs py-2">
                        <span className="font-medium">{l.user_name}</span> - <span className="text-muted-foreground">{l.action}</span>
                      </TableCell>
                      <TableCell className="text-xs py-2 text-muted-foreground">{l.details}</TableCell>
                      <TableCell className="text-xs py-2 text-muted-foreground whitespace-nowrap">{l.created_at ? format(new Date(l.created_at), "MMM d, HH:mm") : ""}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        )}
        {finalizeConfirmation}{deleteConfirmation}
      </div>
    );
  }

  // ========== MAIN VIEW ==========
  return (
    <div className="space-y-6" data-testid="stocktake-page">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Stocktake</h1>
          <p className="text-muted-foreground">Inventory counting, variance tracking & reporting</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchData}><RefreshCw className="w-4 h-4 mr-1" />Refresh</Button>
          <Button onClick={() => setNewDialog(true)} data-testid="new-stocktake-btn"><Plus className="w-4 h-4 mr-1" />New Stocktake</Button>
        </div>
      </div>

      <Tabs value={tab} onValueChange={setTab}>
        <TabsList>
          <TabsTrigger value="sessions" data-testid="tab-stocktake-sessions">Sessions</TabsTrigger>
          <TabsTrigger value="reports" data-testid="tab-stocktake-reports">Reports</TabsTrigger>
        </TabsList>

        <TabsContent value="sessions">
          {/* Shared inventory overview */}
          {report && (
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mt-4">
              <HeroTile label="Stocktake sessions" value={report.total_sessions || 0} icon={ClipboardCheck} glow="cyan" animated={false} />
              <HeroTile label="Stock at cost" value={`$${(report.stock_in_hand_cost || 0).toLocaleString()}`} icon={DollarSign} glow="emerald" animated={false} />
              <HeroTile label="Stock at retail" value={`$${(report.stock_in_hand_retail || 0).toLocaleString()}`} icon={DollarSign} glow="cyan" animated={false} />
              <HeroTile label="Stock loss" value={`$${(report.total_stock_loss || 0).toLocaleString()}`} icon={TrendingDown} glow="rose" animated={false} />
              <HeroTile label="Stock gain" value={`$${(report.total_stock_gain || 0).toLocaleString()}`} icon={TrendingUp} glow="emerald" animated={false} />
            </div>
          )}

          {/* Sessions List */}
          <div className="space-y-3 mt-4">
            {sessions.length === 0 ? (
              <Card className="border-dashed"><CardContent className="py-12 text-center">
                <ClipboardCheck className="w-12 h-12 mx-auto text-muted-foreground mb-3 opacity-30" />
                <p className="text-muted-foreground mb-3">No stocktake sessions yet</p>
                <Button onClick={() => setNewDialog(true)}><Plus className="w-4 h-4 mr-1" />Start First Stocktake</Button>
              </CardContent></Card>
            ) : sessions.map(s => {
              const pct = s.total_items > 0 ? Math.round((s.counted_items / s.total_items) * 100) : 0;
              return (
                <Card key={s.id} className="hover:border-primary/40 transition-colors cursor-pointer" onClick={() => fetchSession(s.id)} data-testid={`stocktake-session-${s.id}`}>
                  <CardContent className="py-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className={`w-11 h-11 rounded-xl flex items-center justify-center ${s.status === "completed" ? "bg-green-500/10" : "bg-yellow-500/10"}`}>
                          <ClipboardCheck className={`w-5 h-5 ${s.status === "completed" ? "text-green-400" : "text-yellow-400"}`} />
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <p className="font-semibold font-mono">{s.session_number}</p>
                            <Badge className={STATUS_COLORS[s.status] + " text-xs"}>{s.status === "in_progress" ? "In Progress" : "Completed"}</Badge>
                          </div>
                          <p className="text-xs text-muted-foreground">{s.name} - {s.location}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-6 text-sm" onClick={e => e.stopPropagation()}>
                        <div className="text-center"><p className="text-xs text-muted-foreground">Items</p><p className="font-medium">{s.counted_items}/{s.total_items}</p></div>
                        <div className="w-24"><Progress value={pct} className="h-2" /><p className="text-[10px] text-muted-foreground text-center mt-1">{pct}%</p></div>
                        {s.stock_loss_value > 0 && <div className="text-center"><p className="text-xs text-muted-foreground">Loss</p><p className="font-medium text-red-400">${s.stock_loss_value?.toFixed(2)}</p></div>}
                        <p className="text-xs text-muted-foreground">{s.created_at ? format(new Date(s.created_at), "MMM d, yyyy") : ""}</p>
                        {s.status === "in_progress" && <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-destructive" title="Delete in-progress stocktake" onClick={() => setDeleteTarget(s)}><Trash2 className="w-3 h-3" /></Button>}
                        <ChevronRight className="w-4 h-4 text-muted-foreground" />
                      </div>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </TabsContent>

        <TabsContent value="reports">
          {report && (
            <div className="space-y-6 mt-4">
              {/* Inventory Overview */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <Card><CardContent className="pt-4"><p className="text-xs text-muted-foreground">Total Products</p><p className="text-2xl font-bold">{report.total_products}</p></CardContent></Card>
                <Card className="border-amber-500/20"><CardContent className="pt-4"><p className="text-xs text-muted-foreground">Low Stock</p><p className="text-2xl font-bold text-amber-400">{report.low_stock_count}</p></CardContent></Card>
                <Card className="border-red-500/20"><CardContent className="pt-4"><p className="text-xs text-muted-foreground">Out of Stock</p><p className="text-2xl font-bold text-red-400">{report.out_of_stock_count}</p></CardContent></Card>
                <Card className="border-cyan-500/20"><CardContent className="pt-4"><p className="text-xs text-muted-foreground">On Order Value</p><p className="text-2xl font-bold text-cyan-400">${report.on_order_value?.toLocaleString()}</p></CardContent></Card>
              </div>

              {/* Stock Value Summary */}
              <Card>
                <CardHeader><CardTitle className="text-sm">Stock Value Summary</CardTitle></CardHeader>
                <CardContent>
                  <div className="grid grid-cols-3 gap-6">
                    <div className="p-4 rounded-lg bg-muted/30 border text-center">
                      <p className="text-xs text-muted-foreground mb-1">Stock in Hand (Cost)</p>
                      <p className="text-3xl font-bold text-green-400">${report.stock_in_hand_cost?.toLocaleString()}</p>
                    </div>
                    <div className="p-4 rounded-lg bg-muted/30 border text-center">
                      <p className="text-xs text-muted-foreground mb-1">Stock in Hand (Retail)</p>
                      <p className="text-3xl font-bold text-cyan-400">${report.stock_in_hand_retail?.toLocaleString()}</p>
                    </div>
                    <div className="p-4 rounded-lg bg-muted/30 border text-center">
                      <p className="text-xs text-muted-foreground mb-1">Net Variance (All Stocktakes)</p>
                      <p className={`text-3xl font-bold ${report.net_variance >= 0 ? "text-green-400" : "text-red-400"}`}>${report.net_variance?.toLocaleString()}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* Low Stock Alerts */}
              {report.low_stock_products?.length > 0 && (
                <Card className="border-amber-500/20">
                  <CardHeader><CardTitle className="text-sm flex items-center gap-2"><AlertTriangle className="w-4 h-4 text-amber-400" />Low Stock Products</CardTitle></CardHeader>
                  <CardContent className="p-0">
                    <Table>
                      <TableHeader><TableRow><TableHead>Product</TableHead><TableHead>SKU</TableHead><TableHead className="text-right">In Stock</TableHead><TableHead className="text-right">Reorder Level</TableHead></TableRow></TableHeader>
                      <TableBody>
                        {report.low_stock_products.map(p => (
                          <TableRow key={p.id}>
                            <TableCell className="font-medium">{p.name}</TableCell>
                            <TableCell className="font-mono text-xs">{p.sku}</TableCell>
                            <TableCell className="text-right font-bold text-red-400">{p.qty}</TableCell>
                            <TableCell className="text-right text-muted-foreground">{p.reorder}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </CardContent>
                </Card>
              )}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* New Session Dialog */}
      <Dialog open={newDialog} onOpenChange={setNewDialog}>
        <DialogContent>
          <DialogHeader><DialogTitle>Start New Stocktake</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div><Label>Session Name</Label><Input value={newForm.name} onChange={e => setNewForm({ ...newForm, name: e.target.value })} placeholder="e.g. Monthly Warehouse Count" data-testid="stocktake-name-input" /></div>
            <div><Label>Description</Label><Textarea value={newForm.description} onChange={e => setNewForm({ ...newForm, description: e.target.value })} placeholder="Notes about this stocktake..." rows={2} /></div>
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Location</Label><Input value={newForm.location} onChange={e => setNewForm({ ...newForm, location: e.target.value })} placeholder="All Locations" /></div>
              <div><Label>Category Filter (optional)</Label>
                <Select value={newForm.category_filter || "all"} onValueChange={v => setNewForm({ ...newForm, category_filter: v === "all" ? "" : v })}>
                  <SelectTrigger><SelectValue placeholder="All categories" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Categories</SelectItem>
                    {["Hardware", "Software", "Licensing", "Services", "Accessories", "Networking", "Security", "Cloud"].map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter><Button onClick={handleCreateSession} data-testid="start-stocktake-btn"><ClipboardCheck className="w-4 h-4 mr-1" />Start Stocktake</Button></DialogFooter>
        </DialogContent>
      </Dialog>
      {deleteConfirmation}
    </div>
  );
}

