              <Label className="text-xs">Job title (drives permission preset)</Label>
              <Select value={form.job_title} onValueChange={v => setForm({ ...form, job_title: v })}>
                <SelectTrigger data-testid="add-user-title"><SelectValue /></SelectTrigger>
