import { useState, useEffect, useMemo, useRef, useCallback } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { Network, Server, Monitor, Laptop, Wifi, Loader2, RefreshCw, Globe, Printer, HardDrive, Shield, Users, AlertTriangle } from "lucide-react";
import OperationalPageHeader from "@/components/OperationalPageHeader";
import HeroTile from "@/components/HeroTile";

const DEVICE_ICONS = { server: Server, workstation: Monitor, laptop: Laptop, router: Globe, switch: Network, firewall: Shield, printer: Printer, other: HardDrive };
const STATUS_COLORS = { online: "#10b981", offline: "#ef4444", warning: "#f59e0b", unknown: "#6b7280" };

function TopologyCanvas({ topology }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !topology?.nodes?.length) return;
    const ctx = canvas.getContext("2d");
    canvas.width = canvas.offsetWidth;
    canvas.height = Math.max(canvas.offsetHeight, 500);
    const W = canvas.width, H = canvas.height;

    // Center nodes
    const offsetX = W / 2;
    const offsetY = 80;

    ctx.clearRect(0, 0, W, H);

    // Draw edges
    topology.edges?.forEach(e => {
      const src = topology.nodes.find(n => n.id === e.source);
      const tgt = topology.nodes.find(n => n.id === e.target);
      if (!src || !tgt) return;
      ctx.beginPath();
      ctx.moveTo(src.x + offsetX, src.y + offsetY);
      ctx.lineTo(tgt.x + offsetX, tgt.y + offsetY);
      ctx.strokeStyle = e.type === "uplink" ? "rgba(59,130,246,0.4)" : "rgba(100,100,100,0.25)";
      ctx.lineWidth = e.type === "uplink" ? 2 : 1;
      ctx.stroke();
    });

    // Draw nodes
    topology.nodes.forEach(n => {
      const x = n.x + offsetX;
      const y = n.y + offsetY;
      const color = STATUS_COLORS[n.status] || STATUS_COLORS.unknown;

      // Glow
      ctx.beginPath();
      ctx.arc(x, y, 24, 0, Math.PI * 2);
      ctx.fillStyle = color + "15";
      ctx.fill();

      // Circle
      ctx.beginPath();
      ctx.arc(x, y, 18, 0, Math.PI * 2);
      ctx.fillStyle = "#1a1a2e";
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Icon text
      const icon = n.type?.[0]?.toUpperCase() || "?";
      ctx.fillStyle = color;
      ctx.font = "bold 12px system-ui";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(icon, x, y);

      // Label
      ctx.fillStyle = "#e5e7eb";
      ctx.font = "11px system-ui";
      ctx.fillText(n.label, x, y + 30);

      // IP
      if (n.ip) {
        ctx.fillStyle = "#6b7280";
        ctx.font = "9px monospace";
        ctx.fillText(n.ip, x, y + 42);
      }

      // Status dot
      ctx.beginPath();
      ctx.arc(x + 14, y - 14, 4, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.fill();
    });
  }, [topology]);

  return <canvas ref={canvasRef} className="w-full h-[500px] rounded-lg" />;
}

export default function TopologyPage() {
  const { token } = useAuth();
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);
  const [clients, setClients] = useState([]);
  const [selectedClient, setSelectedClient] = useState("");
  const [topology, setTopology] = useState(null);
  const [loading, setLoading] = useState(true);
  const [topoLoading, setTopoLoading] = useState(false);

  const loadClients = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/topology/all`, { headers });
      setClients(res.data);
      setSelectedClient(current => current || res.data[0]?.client_id || "");
    } catch { toast.error("Failed to load topology data"); }
    finally { setLoading(false); }
  }, [headers]);

  const loadTopology = useCallback(async (clientId) => {
    if (!clientId) return;
    setTopoLoading(true);
    try {
      const res = await axios.get(`${API}/topology/${clientId}`, { headers });
      setTopology(res.data);
    } catch { toast.error("Failed to load topology"); }
    finally { setTopoLoading(false); }
  }, [headers]);

  useEffect(() => { loadClients(); }, [loadClients]);
  useEffect(() => { loadTopology(selectedClient); }, [selectedClient, loadTopology]);

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin" /></div>;

  const selectedClientSummary = clients.find(client => client.client_id === selectedClient);
  const topologyStats = topology?.stats || {};

  return (
    <div className="space-y-6" data-testid="topology-page">
      <OperationalPageHeader
        eyebrow="Network workspace · topology"
        title="Network topology"
        description="Visual maps of each client network, with a current device health snapshot for fast triage and documentation."
        icon={Network}
        tone="sky"
        actions={(
          <>
            <Select value={selectedClient} onValueChange={setSelectedClient}>
              <SelectTrigger className="w-[280px]" data-testid="client-select"><SelectValue placeholder="Select client..." /></SelectTrigger>
              <SelectContent>{clients.map(c => <SelectItem key={c.client_id} value={c.client_id}>{c.client_name} ({c.device_count} devices)</SelectItem>)}</SelectContent>
            </Select>
            <Button variant="outline" size="sm" onClick={async () => { await loadClients(); await loadTopology(selectedClient); }} disabled={loading || topoLoading} data-testid="topology-refresh-btn">
              {topoLoading ? <Loader2 className="w-3 h-3 mr-1 animate-spin" /> : <RefreshCw className="w-3 h-3 mr-1" />}Refresh
            </Button>
          </>
        )}
      />

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-5">
        <HeroTile label="Client networks" value={clients.length} icon={Users} glow="sky" subtitle="Available topology maps" />
        <HeroTile label="Selected devices" value={topologyStats.total_devices ?? selectedClientSummary?.device_count ?? 0} icon={Monitor} glow="indigo" subtitle={topology?.client_name || "Select a client"} />
        <HeroTile label="Online" value={topologyStats.online ?? 0} icon={Wifi} glow="emerald" subtitle="Nodes reporting normally" />
        <HeroTile label="Offline" value={topologyStats.offline ?? 0} icon={AlertTriangle} glow={(topologyStats.offline ?? 0) > 0 ? "rose" : "zinc"} subtitle={(topologyStats.offline ?? 0) > 0 ? "Review device connectivity" : "No offline nodes"} />
        <HeroTile label="Topology health" value={selectedClientSummary?.health_pct ?? 0} suffix="%" icon={Network} glow="violet" subtitle="Selected client health" />
      </div>

      {/* Client Cards */}
      <div className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-5">
        {clients.slice(0, 10).map(c => (
          <Card key={c.client_id}
            className={`cursor-pointer transition-all hover:border-primary/30 ${selectedClient === c.client_id ? "border-primary ring-1 ring-primary" : ""}`}
            onClick={() => setSelectedClient(c.client_id)}>
            <CardContent className="p-3">
              <p className="font-medium text-sm truncate">{c.client_name}</p>
              <div className="flex items-center justify-between mt-1">
                <span className="text-xs text-muted-foreground">{c.device_count} devices</span>
                <span className={`text-xs font-bold ${c.health_pct >= 90 ? "text-emerald-400" : c.health_pct >= 70 ? "text-amber-400" : "text-red-400"}`}>{c.health_pct}%</span>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Topology Map */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center justify-between">
            <span className="flex items-center gap-2"><Network className="w-4 h-4" />{topology?.client_name || "Select a client"}</span>
            {topology?.stats && (
              <div className="flex gap-3 text-[10px]">
                <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-400" />{topology.stats.online} Online</span>
                <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-red-400" />{topology.stats.offline} Offline</span>
                <span className="text-muted-foreground">{topology.stats.total_devices} total</span>
              </div>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {topoLoading ? (
            <div className="flex items-center justify-center h-[500px]"><Loader2 className="w-8 h-8 animate-spin" /></div>
          ) : topology?.nodes?.length > 0 ? (
            <TopologyCanvas topology={topology} />
          ) : (
            <div className="flex items-center justify-center h-[500px] text-muted-foreground"><Network className="w-12 h-12 opacity-20 mr-3" /><span>No devices found for this client</span></div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "sonner";
import {
  AlertTriangle, Bug, CheckCircle, Clock, ExternalLink, FileWarning, Loader2,
  RefreshCw, ScanSearch, Search, ShieldAlert, Ticket, Undo2,
} from "lucide-react";
import OperationalPageHeader from "@/components/OperationalPageHeader";
import HeroTile from "@/components/HeroTile";

const SEVERITY_STYLE = {
  critical: "border-rose-500/30 bg-rose-500/20 text-rose-300",
  high: "border-orange-500/30 bg-orange-500/20 text-orange-300",
  medium: "border-amber-500/30 bg-amber-500/20 text-amber-300",
  low: "border-sky-500/30 bg-sky-500/20 text-sky-300",
  unclassified: "border-border bg-muted text-muted-foreground",
};

const STATUS_STYLE = {
  open: "text-rose-300",
  patching: "text-amber-300",
  patched: "text-emerald-300",
  accepted_risk: "text-zinc-400",
};

const EMPTY_DATA = {
  summary: { critical: 0, high: 0, medium: 0, low: 0, total: 0, total_hosts_affected: 0, agent_coverage: 0, managed_endpoints: 0 },
  vulnerabilities: [],
};

export default function VulnerabilityScannerPage() {
  const { token } = useAuth();
  const navigate = useNavigate();
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [patchReadyOnly, setPatchReadyOnly] = useState(false);
  const [actioningKey, setActioningKey] = useState(null);
  const [riskDialog, setRiskDialog] = useState(null);
  const [riskReason, setRiskReason] = useState("");

  const fetchData = useCallback(async () => {
    setLoading(true);
    setLoadError("");
    try {
      const res = await axios.get(`${API}/vulnerability-scanner/overview`, { headers });
      setData(res.data);
    } catch (error) {
      const message = error.response?.data?.detail || "Vulnerability evidence could not be loaded. Check the API connection and try again.";
      setLoadError(message);
      toast.error(message);
    } finally {
      setLoading(false);
    }
  }, [headers]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const source = data || EMPTY_DATA;
  const findings = source.vulnerabilities || [];
  const summary = source.summary || EMPTY_DATA.summary;
  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return findings
      .filter((finding) => sevFilter === "all" || finding.severity === sevFilter)
      .filter((finding) => statusFilter === "all" || finding.status === statusFilter)
      .filter((finding) => !patchReadyOnly || finding.patch_available)
      .filter((finding) => !query || [finding.reference, finding.title, finding.device_name, finding.client_name].some((value) => value?.toLowerCase().includes(query)));
  }, [findings, patchReadyOnly, search, sevFilter, statusFilter]);

  const stats = {
    patchReady: findings.filter((finding) => finding.patch_available && finding.status === "open").length,
    active: findings.filter((finding) => finding.status !== "accepted_risk").length,
  };

  const resetFilters = () => { setSevFilter("all"); setStatusFilter("all"); setPatchReadyOnly(false); };

  const createTicket = async (finding) => {
    setActioningKey(finding.finding_key);
    try {
      const res = await axios.post(`${API}/vulnerability-scanner/findings/${encodeURIComponent(finding.finding_key)}/ticket`, {}, { headers });
      const ticket = res.data?.ticket;
      toast.success(res.data?.existing ? "Existing remediation ticket opened" : "Remediation ticket created", {
        action: ticket?.id ? { label: "Open ticket", onClick: () => navigate(`/tickets?ticket=${encodeURIComponent(ticket.id)}`) } : undefined,
      });
    } catch (error) {
      toast.error(error.response?.data?.detail || "Could not create the remediation ticket");
    } finally {
      setActioningKey(null);
    }
  };

  const acceptRisk = async () => {
    if (!riskDialog) return;
    setActioningKey(riskDialog.finding_key);
    try {
      await axios.post(`${API}/vulnerability-scanner/findings/${encodeURIComponent(riskDialog.finding_key)}/accept-risk`, { reason: riskReason }, { headers });
      toast.success("Risk acceptance recorded in the audit trail");
      setRiskDialog(null);
      setRiskReason("");
      await fetchData();
    } catch (error) {
      toast.error(error.response?.data?.detail || "Could not record risk acceptance");
    } finally {
      setActioningKey(null);
    }
  };

  const restoreReview = async (finding) => {
    if (!window.confirm(`Return ${finding.reference || finding.title} to the active security review queue?`)) return;
    setActioningKey(finding.finding_key);
    try {
      await axios.post(`${API}/vulnerability-scanner/findings/${encodeURIComponent(finding.finding_key)}/restore`, {}, { headers });
      toast.success("Finding restored to active review");
      await fetchData();
    } catch (error) {
      toast.error(error.response?.data?.detail || "Could not restore the finding");
    } finally {
      setActioningKey(null);
    }
  };

  if (loadError && !loading) {
    return <div className="space-y-6" data-testid="vulnerability-scanner-error"><OperationalPageHeader eyebrow="Endpoint security - verified exposure" title="Vulnerability scanner" description="Review trusted CVE and operating-system patch evidence." icon={Bug} tone="amber" actions={<Button size="sm" onClick={fetchData}><RefreshCw className="mr-1 h-4 w-4" />Try again</Button>} /><Card className="border-rose-500/30 bg-rose-500/5"><CardContent className="flex items-center gap-3 py-5 text-sm text-rose-100"><AlertTriangle className="h-5 w-5 text-rose-400" />{loadError}</CardContent></Card></div>;
  }

  return (
    <div className="space-y-6" data-testid="vulnerability-scanner">
      <OperationalPageHeader
        eyebrow="Endpoint security - verified exposure"
        title="Vulnerability scanner"
        description={source.scan_note || "Trusted CVE findings and operating-system patch exposure from Nexus Agent telemetry. Findings are never inferred from generic update metadata."}
        icon={Bug}
        tone="amber"
        actions={<><Button variant="outline" size="sm" onClick={() => navigate("/maintenance-scheduler")}><ExternalLink className="mr-1 h-4 w-4" />Maintenance</Button><Button size="sm" onClick={fetchData} disabled={loading}><RefreshCw className={`mr-1 h-4 w-4 ${loading ? "animate-spin" : ""}`} />Refresh evidence</Button></>}
      />

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-3 2xl:grid-cols-6">
        <HeroTile label="Active exposure" value={stats.active} icon={ShieldAlert} glow="indigo" subtitle="Excluding accepted risk" onClick={resetFilters} active={sevFilter === "all" && statusFilter === "all" && !patchReadyOnly} testId="vuln-active-tile" />
        <HeroTile label="Critical" value={summary.critical || 0} icon={AlertTriangle} glow={summary.critical ? "rose" : "zinc"} subtitle="Immediate investigation" onClick={() => { setSevFilter("critical"); setStatusFilter("all"); setPatchReadyOnly(false); }} active={sevFilter === "critical"} testId="vuln-critical-tile" />
        <HeroTile label="High" value={summary.high || 0} icon={AlertTriangle} glow={summary.high ? "amber" : "zinc"} subtitle="Prioritise remediation" onClick={() => { setSevFilter("high"); setStatusFilter("all"); setPatchReadyOnly(false); }} active={sevFilter === "high"} testId="vuln-high-tile" />
        <HeroTile label="Medium" value={summary.medium || 0} icon={Bug} glow={summary.medium ? "amber" : "zinc"} subtitle="Plan corrective action" onClick={() => { setSevFilter("medium"); setStatusFilter("all"); setPatchReadyOnly(false); }} active={sevFilter === "medium"} testId="vuln-medium-tile" />
        <HeroTile label="Patch ready" value={stats.patchReady} icon={CheckCircle} glow={stats.patchReady ? "emerald" : "zinc"} subtitle="Verified update available" onClick={() => { setSevFilter("all"); setStatusFilter("open"); setPatchReadyOnly(true); }} active={patchReadyOnly} testId="vuln-patch-ready-tile" />
        <HeroTile label="Agent coverage" value={`${summary.agent_coverage || 0}/${summary.managed_endpoints || 0}`} icon={ScanSearch} glow="sky" subtitle={`${summary.total_hosts_affected || 0} assets affected`} animated={false} onClick={resetFilters} testId="vuln-agent-coverage-tile" />
      </div>

      {loading ? <div className="flex h-40 items-center justify-center text-muted-foreground"><Loader2 className="h-6 w-6 animate-spin" /></div> : <>
        <div className="flex flex-wrap gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" placeholder="Search reference, asset, or client..." value={search} onChange={(event) => setSearch(event.target.value)} data-testid="vuln-search" /></div><Select value={sevFilter} onValueChange={(value) => { setSevFilter(value); setPatchReadyOnly(false); }}><SelectTrigger className="w-[160px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All severity</SelectItem><SelectItem value="critical">Critical</SelectItem><SelectItem value="high">High</SelectItem><SelectItem value="medium">Medium</SelectItem><SelectItem value="low">Low</SelectItem><SelectItem value="unclassified">Unclassified</SelectItem></SelectContent></Select><Select value={statusFilter} onValueChange={(value) => { setStatusFilter(value); setPatchReadyOnly(false); }}><SelectTrigger className="w-[170px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All review states</SelectItem><SelectItem value="open">Open review</SelectItem><SelectItem value="accepted_risk">Risk accepted</SelectItem></SelectContent></Select><span className="self-center text-xs text-muted-foreground">{filtered.length} shown</span></div>

        <Card><CardContent className="p-0"><div className="max-h-[620px] overflow-y-auto"><Table><TableHeader><TableRow><TableHead>Reference</TableHead><TableHead>Finding</TableHead><TableHead>Asset</TableHead><TableHead>Client</TableHead><TableHead>Severity</TableHead><TableHead>CVSS</TableHead><TableHead>Review state</TableHead><TableHead>Actions</TableHead></TableRow></TableHeader><TableBody>
          {filtered.length === 0 ? <TableRow><TableCell colSpan={8} className="py-12 text-center text-sm text-muted-foreground">No verified findings match the current filter</TableCell></TableRow> : filtered.map((finding) => <TableRow key={finding.finding_key} className={finding.exploited_in_wild ? "bg-rose-500/[0.06]" : ""} data-testid={`vuln-${finding.id}`}><TableCell className="font-mono text-xs text-sky-300">{finding.reference || "Pending reference"}{finding.exploited_in_wild && <div className="mt-1 text-[10px] font-semibold uppercase tracking-wide text-rose-300">Exploited in the wild</div>}</TableCell><TableCell className="max-w-xs"><div className="truncate text-sm">{finding.title}</div><div className="mt-1 text-[10px] text-muted-foreground">{finding.evidence || "Verified provider evidence"}</div>{finding.risk_acceptance && <div className="mt-1 text-[10px] text-zinc-400">Accepted: {finding.risk_acceptance}</div>}</TableCell><TableCell>{finding.device_id ? <Button variant="link" size="sm" className="h-auto p-0 text-xs" onClick={() => navigate(`/devices/${encodeURIComponent(finding.device_id)}`)}>{finding.device_name || "Open asset"}</Button> : <span className="text-xs text-muted-foreground">Not linked</span>}</TableCell><TableCell>{finding.client_id ? <Button variant="link" size="sm" className="h-auto p-0 text-xs" onClick={() => navigate(`/clients?client=${encodeURIComponent(finding.client_id)}`)}>{finding.client_name}</Button> : <span className="text-xs text-muted-foreground">{finding.client_name || "Unassigned"}</span>}</TableCell><TableCell><Badge variant="outline" className={`text-[10px] uppercase ${SEVERITY_STYLE[finding.severity] || SEVERITY_STYLE.unclassified}`}>{finding.severity}</Badge></TableCell><TableCell><div className={`flex h-8 w-8 items-center justify-center rounded-full text-[10px] font-bold ${finding.cvss == null ? "bg-muted text-muted-foreground" : finding.cvss >= 9 ? "bg-rose-500/20 text-rose-300" : finding.cvss >= 7 ? "bg-orange-500/20 text-orange-300" : finding.cvss >= 4 ? "bg-amber-500/20 text-amber-300" : "bg-sky-500/20 text-sky-300"}`}>{finding.cvss ?? "-"}</div></TableCell><TableCell><div className={`text-xs capitalize ${STATUS_STYLE[finding.status] || "text-muted-foreground"}`}>{finding.status?.replace(/_/g, " ")}</div><div className="mt-1 flex items-center gap-1 text-[10px] text-muted-foreground">{finding.patch_available ? <CheckCircle className="h-3 w-3 text-emerald-300" /> : <Clock className="h-3 w-3 text-amber-300" />}{finding.patch_available ? "Patch ready" : "Mitigation review"}</div></TableCell><TableCell><div className="flex justify-end gap-1"><Button size="sm" variant="ghost" className="h-7 px-2 text-[10px] text-sky-300" onClick={() => navigate("/maintenance-scheduler")}><ExternalLink className="mr-0.5 h-3 w-3" />Patch</Button>{finding.status === "accepted_risk" ? <Button size="sm" variant="ghost" className="h-7 px-2 text-[10px] text-amber-200" disabled={actioningKey === finding.finding_key} onClick={() => restoreReview(finding)}><Undo2 className="mr-0.5 h-3 w-3" />Restore</Button> : <><Button size="sm" variant="ghost" className="h-7 px-2 text-[10px] text-emerald-300" disabled={actioningKey === finding.finding_key} onClick={() => createTicket(finding)}><Ticket className="mr-0.5 h-3 w-3" />Ticket</Button><Button size="sm" variant="ghost" className="h-7 px-2 text-[10px] text-muted-foreground" disabled={actioningKey === finding.finding_key} onClick={() => { setRiskReason(""); setRiskDialog(finding); }}><FileWarning className="mr-0.5 h-3 w-3" />Risk</Button></>}</div></TableCell></TableRow>)}
        </TableBody></Table></div></CardContent></Card>
      </>}

      <Dialog open={!!riskDialog} onOpenChange={(open) => !open && setRiskDialog(null)}><DialogContent className="max-w-lg" data-testid="vuln-risk-dialog"><DialogHeader><DialogTitle className="flex items-center gap-2"><FileWarning className="h-4 w-4 text-amber-300" />Accept security risk</DialogTitle></DialogHeader><div className="space-y-3"><p className="text-sm text-muted-foreground">This keeps the source evidence visible, changes the item to <strong>Risk accepted</strong>, and records your identity, timestamp, and reason in the central audit trail.</p><div className="rounded-lg border border-border bg-muted/30 p-3 text-sm"><div className="font-medium">{riskDialog?.reference || riskDialog?.title}</div><div className="mt-1 text-xs text-muted-foreground">{riskDialog?.client_name} - {riskDialog?.device_name || "No linked asset"}</div></div><Textarea value={riskReason} onChange={(event) => setRiskReason(event.target.value)} rows={5} placeholder="Why is this risk accepted, and what compensating controls apply?" data-testid="vuln-risk-reason" /><div className="flex justify-end gap-2"><Button variant="outline" onClick={() => setRiskDialog(null)} disabled={actioningKey === riskDialog?.finding_key}>Cancel</Button><Button variant="destructive" onClick={acceptRisk} disabled={riskReason.trim().length < 8 || actioningKey === riskDialog?.finding_key}>{actioningKey === riskDialog?.finding_key && <Loader2 className="mr-1 h-4 w-4 animate-spin" />}Record acceptance</Button></div></div></DialogContent></Dialog>
    </div>
  );
}

