function WarRoomList() {
  const { token } = useAuth();
  const navigate = useNavigate();
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [includeResolved, setIncludeResolved] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState({ title: "", severity: "P1", summary: "", client_id: "", ticket_id: "" });
  const [clients, setClients] = useState([]);
  const [tickets, setTickets] = useState([]);
  const [clientQuery, setClientQuery] = useState("");
  const [ticketQuery, setTicketQuery] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/warroom?include_resolved=${includeResolved}`, { headers });
      setRooms(res.data || []);
    } catch (e) { toast.error("Load failed"); }
    finally { setLoading(false); }
  }, [headers, includeResolved]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    (async () => {
      try {
        const res = await axios.get(`${API}/clients`, { headers });
        setClients(res.data || []);
      } catch {}
    })();
  }, [headers]);
  useEffect(() => {
    if (!form.client_id) { setTickets([]); return; }
    axios.get(`${API}/tickets?client_id=${form.client_id}`, { headers }).then(res => setTickets(res.data || [])).catch(() => setTickets([]));
  }, [form.client_id, headers]);

  const chooseClient = value => {
    const match = clients.find(client => client.name.toLowerCase() === value.trim().toLowerCase());
    setClientQuery(value);
    setTicketQuery("");
    setForm(current => ({ ...current, client_id: match?.id || "", ticket_id: "" }));
  };
  const ticketLabel = ticket => [ticket.ticket_number ? `#${ticket.ticket_number}` : "Ticket", ticket.title].filter(Boolean).join(" - ");
  const chooseTicket = value => {
    const match = tickets.find(ticket => ticketLabel(ticket).toLowerCase() === value.trim().toLowerCase());
    setTicketQuery(value);
    setForm(current => ({ ...current, ticket_id: match?.id || "" }));
  };

  const create = async () => {
    if (!form.title.trim()) { toast.error("Title required"); return; }
    setCreating(true);
    try {
      const res = await axios.post(`${API}/warroom`, form, { headers });
      toast.success("War room opened");
      setCreateOpen(false);
      setForm({ title: "", severity: "P1", summary: "", client_id: "", ticket_id: "" });
      setClientQuery("");
      setTicketQuery("");
      navigate(`/warroom/${res.data.war_room.id}`);
    } catch (e) { toast.error(e.response?.data?.detail || e.message); }
    finally { setCreating(false); }
  };

  const active = rooms.filter(r => r.status !== "resolved");
  const resolved = rooms.filter(r => r.status === "resolved");

  return (
    <div className="space-y-6" data-testid="warroom-list-page">
      <OperationalPageHeader
        eyebrow="Incident command · real-time response and client communication"
        title="War Rooms"
        description="Open a focused incident workspace with a technician bridge, live status, paging controls, evidence and a client-safe update link."
        icon={Siren}
        tone="amber"
        actions={<>
          <Button variant="outline" size="sm" onClick={() => setIncludeResolved(v => !v)} data-testid="warroom-toggle-resolved">{includeResolved ? "Active only" : "Show resolved"}</Button>
          <Button variant="outline" size="sm" onClick={load} disabled={loading}><RefreshCw className={`mr-1.5 h-4 w-4 ${loading ? "animate-spin" : ""}`} />Refresh</Button>
          <Button onClick={() => setCreateOpen(true)} data-testid="warroom-new-btn"><Siren className="mr-1.5 h-4 w-4" />Open war room</Button>
        </>}
      />

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-5">
        <HeroTile label="Active rooms" value={active.length} icon={Siren} glow={active.length ? "rose" : "zinc"} subtitle="Live incident workspaces" testId="warroom-metric-active" />
        <HeroTile label="Investigating" value={active.filter(r => r.status === "investigating").length} icon={AlertTriangle} glow="rose" subtitle="Initial response in progress" testId="warroom-metric-investigating" />
        <HeroTile label="Identified" value={active.filter(r => r.status === "identified").length} icon={Activity} glow="amber" subtitle="Root cause or scope known" testId="warroom-metric-identified" />
        <HeroTile label="Monitoring" value={active.filter(r => r.status === "monitoring").length} icon={Eye} glow="sky" subtitle="Validation underway" testId="warroom-metric-monitoring" />
        <HeroTile label="Resolved" value={resolved.length} icon={CheckCircle2} glow="emerald" subtitle={includeResolved ? "Included in this view" : "Enable history to review"} testId="warroom-metric-resolved" />
      </div>

      <Card className="border-border/80 bg-card/80">
        <CardContent className="p-0">
          {loading ? (
            <div className="p-12 text-center text-muted-foreground"><Loader2 className="w-5 h-5 animate-spin inline mr-2" /> Loading…</div>
          ) : rooms.length === 0 ? (
            <div className="p-16 text-center text-sm text-muted-foreground">
              No war rooms. When a P1 fires, open one to give your techs a single battle-station.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Incident</TableHead>
                  <TableHead>Client</TableHead>
                  <TableHead>Severity</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>ETA</TableHead>
                  <TableHead>Opened</TableHead>
                  <TableHead></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {[...active, ...resolved].map(r => (
                  <TableRow key={r.id} className="cursor-pointer hover:bg-muted/30" onClick={() => navigate(`/warroom/${r.id}`)} data-testid={`warroom-row-${r.id}`}>
                    <TableCell className="text-sm font-medium">{r.title}</TableCell>
                    <TableCell className="text-sm">{r.client_name || "—"}</TableCell>
                    <TableCell><Badge variant="outline" className={SEVERITY_CLS[r.severity] || ""}>{r.severity}</Badge></TableCell>
                    <TableCell><Badge variant="outline" className={STATUS_CLS[r.status]}>{r.status}</Badge></TableCell>
                    <TableCell className="text-xs">{r.eta || "—"}</TableCell>
                    <TableCell className="text-xs text-muted-foreground">{timeAgo(r.created_at)} · by {r.created_by}</TableCell>
                    <TableCell><ChevronRight className="w-4 h-4 opacity-40" /></TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent className="max-h-[92vh] max-w-3xl overflow-y-auto p-0" data-testid="warroom-create-dialog">
          <DialogHeader className="border-b border-border/80 px-6 py-5"><DialogTitle className="flex items-center gap-2"><Siren className="h-5 w-5 text-rose-300" />Open incident war room</DialogTitle><p className="text-sm text-muted-foreground">Create the response bridge first, then use it as the complete record for coordination, updates, paging and follow-up.</p></DialogHeader>
          <div className="space-y-5 px-6 py-5">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="md:col-span-2"><Label htmlFor="warroom-title-input">Incident title</Label><Input id="warroom-title-input" className="mt-1" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="e.g. ACME Corp VPN outage" data-testid="warroom-title" /></div>
              <div><Label>Severity</Label><Select value={form.severity} onValueChange={(v) => setForm({ ...form, severity: v })}><SelectTrigger className="mt-1" data-testid="warroom-severity"><SelectValue /></SelectTrigger><SelectContent>{["P1", "P2", "P3", "P4"].map(s => <SelectItem key={s} value={s}>{s} · {s === "P1" ? "critical" : s === "P2" ? "high impact" : s === "P3" ? "standard" : "low impact"}</SelectItem>)}</SelectContent></Select></div>
              <div><Label htmlFor="warroom-client-input">Client</Label><Input id="warroom-client-input" list="warroom-client-options" className="mt-1" value={clientQuery} onChange={event => chooseClient(event.target.value)} placeholder="Type to find a client" data-testid="warroom-client" /><datalist id="warroom-client-options">{clients.map((client, index) => <option key={`${client.id}-${index}`} value={client.name} />)}</datalist></div>
              <div className="md:col-span-2"><Label htmlFor="warroom-ticket-input">Related ticket</Label><Input id="warroom-ticket-input" list="warroom-ticket-options" className="mt-1" value={ticketQuery} onChange={event => chooseTicket(event.target.value)} placeholder={form.client_id ? "Type to link a client ticket" : "Choose a client to search their tickets"} disabled={!form.client_id} /><datalist id="warroom-ticket-options">{tickets.map((ticket, index) => <option key={`${ticket.id}-${index}`} value={ticketLabel(ticket)} />)}</datalist><p className="mt-1 text-[11px] text-muted-foreground">Linking the affected ticket keeps the response, device context and later post-incident reporting connected.</p></div>
              <div className="md:col-span-2"><Label htmlFor="warroom-summary">Initial situation brief</Label><Textarea id="warroom-summary" className="mt-1" rows={4} value={form.summary} onChange={(e) => setForm({ ...form, summary: e.target.value })} placeholder="What is affected, what is known, what has been tried, and when will the next client update be due?" /></div>
            </div>
          </div>
          <DialogFooter className="border-t border-border/80 px-6 py-4"><Button variant="outline" onClick={() => setCreateOpen(false)}>Cancel</Button><Button onClick={create} disabled={creating || !form.title.trim()} data-testid="warroom-create-submit">{creating ? <Loader2 className="mr-1.5 h-4 w-4 animate-spin" /> : <Siren className="mr-1.5 h-4 w-4" />}Open war room</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function WarRoomDetail({ wrId }) {
  const { token } = useAuth();
  const navigate = useNavigate();
  const [search] = useSearchParams();
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);
  const [wr, setWr] = useState(null);
  const [msg, setMsg] = useState("");
  const [sending, setSending] = useState(false);
  const [etaDraft, setEtaDraft] = useState("");
  const [statusDraft, setStatusDraft] = useState("");
  const [updating, setUpdating] = useState(false);
  const [pageOpen, setPageOpen] = useState(false);
  const messagesRef = useRef(null);

  const load = useCallback(async (showSpinner = false) => {
    try {
      const res = await axios.get(`${API}/warroom/${wrId}`, { headers });
      setWr(res.data);
      if (!etaDraft) setEtaDraft(res.data.eta || "");
      if (!statusDraft) setStatusDraft(res.data.status);
    } catch (e) {
      if (showSpinner) toast.error("Load failed: " + (e.response?.data?.detail || e.message));
    }
  }, [headers, wrId, etaDraft, statusDraft]);

  useEffect(() => { load(true); }, [wrId]); // eslint-disable-line
  useEffect(() => {
    if (wr?.status === "resolved") return;
    const iv = setInterval(load, 4000);
    return () => clearInterval(iv);
  }, [load, wr?.status]);
  useEffect(() => {
    if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight;
  }, [wr?.messages?.length]);

  if (!wr) {
    return <div className="p-8 text-center text-muted-foreground"><Loader2 className="w-5 h-5 animate-spin inline mr-2" />Loading war room…</div>;
  }

  const publicUrl = `${window.location.origin}/warroom/public/${wr.public_slug}`;

  const sendMessage = async () => {
    if (!msg.trim()) return;
    setSending(true);
    try {
      await axios.post(`${API}/warroom/${wrId}/messages`, { body: msg }, { headers });
      setMsg("");
      load();
    } catch (e) { toast.error(e.response?.data?.detail || e.message); }
    finally { setSending(false); }
  };

  const updateStatus = async (patch) => {
    setUpdating(true);
    try {
      await axios.post(`${API}/warroom/${wrId}/status`, patch, { headers });
      load();
    } catch (e) { toast.error(e.response?.data?.detail || e.message); }
    finally { setUpdating(false); }
  };

  const resolve = async () => {
    if (!window.confirm("Mark this war room resolved?")) return;
    const notes = window.prompt("Resolution notes (optional)") || "";
    try {
      await axios.post(`${API}/warroom/${wrId}/resolve`, { resolved_notes: notes }, { headers });
      toast.success("Resolved");
      load();
    } catch (e) { toast.error(e.response?.data?.detail || e.message); }
  };

  return (
    <div className="space-y-4" data-testid="warroom-detail-page">
      <section className="rounded-2xl border border-rose-500/20 bg-gradient-to-br from-rose-500/[0.11] via-background to-background p-5 md:p-6">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="text-[10px] font-semibold uppercase tracking-[0.22em] text-rose-300">Incident command · live response</p><Badge variant="outline" className={SEVERITY_CLS[wr.severity]}>{wr.severity}</Badge><Badge variant="outline" className={STATUS_CLS[wr.status]}>{wr.status}</Badge></div><h1 className="mt-1 flex items-center gap-2 text-2xl font-semibold tracking-tight" data-testid="warroom-title"><Siren className="h-6 w-6 shrink-0 text-rose-300" />{wr.title}</h1><p className="mt-2 text-sm text-muted-foreground">{wr.client_name || "No client linked"} · opened {timeAgo(wr.created_at)} by {wr.created_by}{wr.resolved_at && ` · resolved ${timeAgo(wr.resolved_at)}`}</p></div>
          <div className="flex flex-wrap items-center gap-2 xl:justify-end">
          <Button variant="outline" size="sm" onClick={() => navigate("/warroom")}><ArrowLeft className="mr-1.5 h-4 w-4" />All war rooms</Button>
          <Button
            variant="outline" size="sm" className="border-rose-500/30 text-rose-200 hover:bg-rose-500/10"
            onClick={() => setPageOpen(true)}
            disabled={wr.status === "resolved"}
            data-testid="warroom-page-btn"
          >
            <Megaphone className="w-3.5 h-3.5 mr-1" />Page Team
          </Button>
          <Button variant="outline" size="sm" onClick={() => { navigator.clipboard.writeText(publicUrl); toast.success("Public status URL copied"); }} data-testid="warroom-share-btn">
            <Share2 className="w-3.5 h-3.5 mr-1" />Share
          </Button>
          {wr.status !== "resolved" && (
            <Button variant="outline" size="sm" className="text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/10" onClick={resolve} data-testid="warroom-resolve-btn">
              <CheckCircle2 className="w-3.5 h-3.5 mr-1" />Resolve
            </Button>
          )}
          {wr.status === "resolved" && <PostmortemButton warRoomId={wr.id} />}
          </div>
        </div>
      </section>

      <div className="grid h-[calc(100vh-280px)] min-h-[620px] grid-cols-12 gap-3 overflow-hidden">
        {/* LEFT sidebar: context */}
        <div className="col-span-3 overflow-y-auto space-y-3">
          <Card>
            <CardContent className="p-3 space-y-2">
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1"><Clock className="w-3 h-3" /> ETA</div>
              <Input
                value={etaDraft}
                onChange={(e) => setEtaDraft(e.target.value)}
                onBlur={() => etaDraft !== (wr.eta || "") && updateStatus({ eta: etaDraft })}
                placeholder="e.g. 15 min"
                className="h-8 text-xs"
                disabled={wr.status === "resolved"}
                data-testid="warroom-eta"
              />
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1 pt-1"><Activity className="w-3 h-3" /> Status</div>
              <Select value={statusDraft} onValueChange={(v) => { setStatusDraft(v); updateStatus({ status: v }); }} disabled={wr.status === "resolved"}>
                <SelectTrigger className="h-8 text-xs" data-testid="warroom-status-select"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="investigating">Investigating</SelectItem>
                  <SelectItem value="identified">Identified</SelectItem>
                  <SelectItem value="monitoring">Monitoring</SelectItem>
                  <SelectItem value="resolved">Resolved</SelectItem>
                </SelectContent>
              </Select>
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground pt-2 flex items-center gap-1"><Users className="w-3 h-3" /> Participants ({wr.participants?.length || 0})</div>
              <div className="flex flex-wrap gap-1">
                {(wr.participants || []).map((p, i) => (
                  <Badge key={i} variant="outline" className="text-[9px]">{p.name}</Badge>
                ))}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-3 space-y-2">
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1"><Link2 className="w-3 h-3" /> Client status URL</div>
              <div className="flex items-center gap-1">
                <Input readOnly value={publicUrl} className="h-7 text-[10px] font-mono" data-testid="warroom-public-url" />
                <Button size="sm" variant="ghost" className="h-7 w-7 p-0" onClick={() => { navigator.clipboard.writeText(publicUrl); toast.success("Copied"); }}><Copy className="w-3 h-3" /></Button>
              </div>
              <p className="text-[9px] text-muted-foreground leading-tight">Share with client — no login needed. Techs' private chat stays hidden.</p>
            </CardContent>
          </Card>

          {wr.pages?.length > 0 && (
            <Card>
              <CardContent className="p-3">
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1 mb-2">
                  <Megaphone className="w-3 h-3" /> Escalation Ladder
                  {wr.auto_escalate && wr.next_escalation_at && (
                    <Badge variant="outline" className="ml-auto text-[9px] text-amber-400 border-amber-500/30">
                      <Clock className="w-2.5 h-2.5 mr-1" />Next: {timeAgo(wr.next_escalation_at)}
                    </Badge>
                  )}
                </div>
                <div className="space-y-1.5">
                  {wr.pages.map((p) => (
                    <div key={p.id} className={`flex items-center gap-2 text-xs rounded px-2 py-1 ${p.status === "ack" ? "bg-emerald-500/10 border border-emerald-500/20" : p.status === "sent" ? "bg-zinc-800/60" : "bg-zinc-900/40 opacity-70"}`} data-testid={`warroom-page-${p.id}`}>
                      <Badge variant="outline" className={`text-[9px] ${p.tier === 1 ? "text-rose-400 border-rose-500/30" : p.tier === 2 ? "text-amber-400 border-amber-500/30" : "text-sky-400 border-sky-500/30"}`}>T{p.tier}</Badge>
                      <div className="flex-1 min-w-0">
                        <div className="font-medium truncate">{p.name}</div>
                        <div className="text-[9px] text-muted-foreground font-mono truncate">{(p.channels || []).join(" · ")}</div>
                      </div>
                      {p.status === "ack" ? (
                        <Badge variant="outline" className="text-[9px] text-emerald-400 border-emerald-500/30"><CheckCircle2 className="w-2.5 h-2.5 mr-0.5" />ACK</Badge>
                      ) : p.status === "sent" ? (
                        <Badge variant="outline" className="text-[9px] text-zinc-400 border-zinc-600">sent</Badge>
                      ) : (
                        <Badge variant="outline" className="text-[9px] text-zinc-500 border-zinc-700">pending</Badge>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {wr.affected_devices?.length > 0 && (
            <Card>
              <CardContent className="p-3">
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1 mb-2"><Server className="w-3 h-3" /> Affected devices</div>
                {wr.affected_devices.map(d => (
                  <Link to={`/devices/${d.id}`} key={d.id} className="block hover:bg-muted/40 rounded px-2 py-1">
                    <div className="text-xs font-medium">{d.name}</div>
                    <div className="text-[10px] text-muted-foreground flex items-center gap-1">
                      <Badge variant="outline" className={d.status === "online" ? "text-emerald-400 border-emerald-500/30 text-[9px]" : "text-rose-400 border-rose-500/30 text-[9px]"}>{d.status}</Badge>
                      <span>{d.ip_address}</span>
                    </div>
                  </Link>
                ))}
              </CardContent>
            </Card>
          )}
        </div>

        {/* CENTER: Chat + messages */}
        <div className="col-span-6 flex flex-col overflow-hidden">
          <Card className="flex flex-1 flex-col overflow-hidden border-border/80 bg-card/90 shadow-lg shadow-black/10">
            <div className="flex items-center gap-2 border-b border-border/80 bg-gradient-to-r from-cyan-500/[0.06] to-transparent px-4 py-3 text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">
              <span className="relative flex h-2 w-2"><span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-75" /><span className="relative inline-flex h-2 w-2 rounded-full bg-emerald-400" /></span><MessageSquare className="h-3.5 w-3.5 text-cyan-300" />Live response bridge <span className="ml-auto normal-case tracking-normal text-muted-foreground">{wr.messages?.length || 0} updates</span>
            </div>
            <div ref={messagesRef} className="flex-1 space-y-2 overflow-y-auto p-4" data-testid="warroom-messages">
              {(wr.messages || []).map(m => (
                <div key={m.id} className={m.kind === "system" ? "mx-auto max-w-[90%] rounded-lg border border-cyan-500/15 bg-cyan-500/[0.04] px-3 py-2 text-center text-[10px] text-cyan-100/70" : "rounded-xl border border-border/75 bg-muted/20 p-3 shadow-sm"}>
                  {m.kind === "system" ? (
                    <div>⊙ {m.body} · <span className="text-[9px]">{timeAgo(m.ts)}</span></div>
                  ) : (
                    <>
                      <div className="text-[10px] text-muted-foreground font-medium">{m.author} · <span className="text-[9px]">{timeAgo(m.ts)}</span></div>
                      <div className="text-sm whitespace-pre-wrap">{m.body}</div>
                    </>
                  )}
                </div>
              ))}
              {(!wr.messages || wr.messages.length === 0) && <div className="text-center text-xs text-muted-foreground py-6">Drop the first update…</div>}
            </div>
            <div className="flex items-center gap-2 border-t border-border/80 bg-muted/15 p-3">
              <Input
                value={msg}
                onChange={(e) => setMsg(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey && !sending) { e.preventDefault(); sendMessage(); } }}
                placeholder={wr.status === "resolved" ? "War room resolved" : "Type update… Enter to send"}
                disabled={sending || wr.status === "resolved"}
                data-testid="warroom-message-input"
              />
              <Button size="sm" onClick={sendMessage} disabled={sending || !msg.trim() || wr.status === "resolved"} data-testid="warroom-send-btn">
                {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              </Button>
            </div>
          </Card>
        </div>

        {/* RIGHT: similar incidents */}
        <div className="col-span-3 overflow-y-auto">
          <Card>
            <CardContent className="p-3">
              <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1 mb-2">
                <Zap className="w-3 h-3" /> Past similar incidents
              </div>
              {(wr.similar_incidents || []).length === 0 ? (
                <div className="text-[11px] text-muted-foreground py-3 text-center">No similar past incidents found.</div>
              ) : (
                <div className="space-y-2">
                  {wr.similar_incidents.map(si => (
                    <Link key={si.ticket_id} to={`/tickets?ticket=${si.ticket_id}`} className="block bg-muted/30 hover:bg-muted/50 rounded-md p-2">
                      <div className="text-xs font-medium line-clamp-1">{si.title}</div>
                      <div className="text-[10px] text-muted-foreground line-clamp-2 mt-0.5">
                        {si.resolution || <em>No resolution recorded</em>}
                      </div>
                      <div className="text-[9px] text-muted-foreground mt-1">Resolved {timeAgo(si.resolved_at)}</div>
                    </Link>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          {wr.summary && (
            <Card className="mt-3">
              <CardContent className="p-3">
                <div className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-1 mb-2"><FileText className="w-3 h-3" /> Summary</div>
                <p className="text-xs whitespace-pre-wrap">{wr.summary}</p>
              </CardContent>
            </Card>
          )}

          {wr.resolved_notes && (
            <Card className="mt-3 border-emerald-500/30 bg-emerald-500/5">
              <CardContent className="p-3">
                <div className="text-[10px] uppercase tracking-widest text-emerald-400 flex items-center gap-1 mb-2"><CheckCircle2 className="w-3 h-3" /> Resolution</div>
                <p className="text-xs whitespace-pre-wrap">{wr.resolved_notes}</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>

      <PageTeamDialog
        open={pageOpen}
        onOpenChange={setPageOpen}
        wrId={wrId}
        headers={headers}
        onPaged={() => load()}
      />
    </div>
  );
}

function PageTeamDialog({ open, onOpenChange, wrId, headers, onPaged }) {
  const [techs, setTechs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selected, setSelected] = useState(new Set());
  const [channels, setChannels] = useState(new Set(["email", "push", "sms"]));
  const [autoEscalate, setAutoEscalate] = useState(true);
  const [grace, setGrace] = useState(5);
  const [sending, setSending] = useState(false);

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    axios.get(`${API}/tech-roster?active_only=true`, { headers })
      .then((r) => {
        setTechs(r.data || []);
        // Pre-select tier-1 on-call techs
        const pre = new Set((r.data || []).filter((t) => t.escalation_tier === 1).map((t) => t.id));
        setSelected(pre);
      })
      .catch(() => toast.error("Failed to load roster"))
      .finally(() => setLoading(false));
  }, [open, headers]);

  const toggle = (id) => {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const toggleChannel = (c) => {
    setChannels((prev) => {
      const next = new Set(prev);
      next.has(c) ? next.delete(c) : next.add(c);
      return next;
    });
  };

  const fire = async () => {
    if (selected.size === 0) { toast.error("Pick at least one tech"); return; }
    setSending(true);
    try {
      await axios.post(
        `${API}/warroom/${wrId}/page`,
        {
          tech_ids: Array.from(selected),
          channels: Array.from(channels),
          auto_escalate: autoEscalate,
          grace_minutes: grace,
        },
        { headers },
      );
      toast.success(autoEscalate ? "Tier 1 paged — escalation armed" : `Paged ${selected.size} tech(s)`);
      onOpenChange(false);
      onPaged && onPaged();
    } catch (e) { toast.error(e.response?.data?.detail || e.message); }
    finally { setSending(false); }
  };

  const groups = { 1: [], 2: [], 3: [] };
  techs.forEach((t) => groups[t.escalation_tier || 2]?.push(t));

  const CHS = [
    { k: "slack", l: "Slack" }, { k: "teams", l: "Teams" }, { k: "sms", l: "SMS" },
    { k: "email", l: "Email" }, { k: "push", l: "In-app" },
  ];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[92vh] max-w-2xl overflow-y-auto p-0" data-testid="warroom-page-dialog">
        <DialogHeader className="border-b border-border/80 px-6 py-5"><DialogTitle className="flex items-center gap-2"><Megaphone className="h-5 w-5 text-rose-300" />Page response team</DialogTitle><p className="text-sm text-muted-foreground">Choose who is paged, how they are notified, and whether NexusMSP should escalate if the first responders do not acknowledge.</p></DialogHeader>
        <div className="space-y-4 px-6 py-5">
          <div className="flex items-center justify-between bg-muted/30 rounded-md px-3 py-2">
            <div>
              <div className="text-sm font-medium flex items-center gap-2">
                <ChevronUp className="w-4 h-4 text-rose-400" /> Auto-Escalate
              </div>
              <div className="text-[10px] text-muted-foreground">Fires Tier 1 now · escalates to Tier 2 then Tier 3 if no ack</div>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-1">
                <Label className="text-[10px] text-muted-foreground">Grace</Label>
                <Input type="number" min={1} max={60} value={grace} onChange={(e) => setGrace(parseInt(e.target.value) || 5)} className="h-7 w-14 text-xs" data-testid="warroom-page-grace" />
                <span className="text-[10px] text-muted-foreground">min</span>
              </div>
              <Switch checked={autoEscalate} onCheckedChange={setAutoEscalate} data-testid="warroom-page-autoescalate" />
            </div>
          </div>

          <div>
            <Label className="text-xs text-muted-foreground">Channels</Label>
            <div className="flex flex-wrap gap-2 mt-1.5">
              {CHS.map(({ k, l }) => (
                <button
                  key={k}
                  type="button"
                  onClick={() => toggleChannel(k)}
                  className={`px-3 py-1 rounded-md border text-xs ${channels.has(k) ? "bg-sky-500/10 border-sky-500/40 text-sky-300" : "border-zinc-700 text-zinc-400 hover:border-zinc-500"}`}
                  data-testid={`warroom-page-ch-${k}`}
                >{l}</button>
              ))}
            </div>
          </div>

          <div>
            <Label className="text-xs text-muted-foreground">Technicians</Label>
            {loading ? (
              <div className="py-8 text-center text-muted-foreground"><Loader2 className="w-4 h-4 animate-spin inline mr-2" />Loading roster…</div>
            ) : techs.length === 0 ? (
              <div className="py-6 text-center text-xs text-muted-foreground">
                No technicians in roster. <Link to="/tech-roster" className="text-sky-400 underline">Add some</Link> to enable paging.
              </div>
            ) : (
              <div className="space-y-3 max-h-72 overflow-y-auto mt-1.5 pr-1">
                {[1, 2, 3].map((tier) => groups[tier].length > 0 && (
                  <div key={tier}>
                    <div className={`text-[10px] uppercase tracking-widest font-semibold mb-1 ${tier === 1 ? "text-rose-400" : tier === 2 ? "text-amber-400" : "text-sky-400"}`}>
                      Tier {tier}
                    </div>
                    <div className="space-y-1">
                      {groups[tier].map((t) => (
                        <label key={t.id} className="flex items-center gap-2 bg-muted/30 hover:bg-muted/50 rounded px-2 py-1.5 cursor-pointer" data-testid={`warroom-page-tech-${t.id}`}>
                          <input type="checkbox" checked={selected.has(t.id)} onChange={() => toggle(t.id)} className="accent-rose-500" />
                          <div className="flex-1 min-w-0">
                            <div className="text-sm font-medium flex items-center gap-2">
                              {t.name}
                              {t.on_call && <Badge variant="outline" className="text-[9px] text-emerald-400 border-emerald-500/30">ON-CALL</Badge>}
                            </div>
                            <div className="text-[10px] text-muted-foreground">{t.role || ""}{t.mobile ? ` · ${t.mobile}` : ""}</div>
                          </div>
                          <div className="text-[9px] text-muted-foreground font-mono">{(t.preferred_channels || []).join("/")}</div>
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
        <DialogFooter className="border-t border-border/80 px-6 py-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button
            onClick={fire}
            disabled={sending || selected.size === 0}
            data-testid="warroom-page-fire-btn"
          >
            {sending ? <Loader2 className="w-4 h-4 animate-spin mr-1" /> : <Megaphone className="w-4 h-4 mr-1" />}
            {autoEscalate ? "Fire Tier 1 · Arm escalation" : `Page ${selected.size} now`}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useCallback, useMemo } from "react";
import axios from "axios";
import { API, useAuth } from "@/App";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { MetricStrip, MetricTile } from "@/components/design-system";
import { toast } from "sonner";
import {
  Wrench, Search, RefreshCw, Loader2, Clock, AlertTriangle, Plus, GripVertical, Monitor, Timer
} from "lucide-react";

const BENCH_COLUMNS = [
  { id: "intake", title: "Intake", color: "border-t-blue-500", dot: "bg-blue-400", desc: "Received, awaiting diagnosis" },
  { id: "diagnosing", title: "Diagnosing", color: "border-t-amber-500", dot: "bg-amber-400", desc: "Under investigation" },
  { id: "parts_ordered", title: "Parts Ordered", color: "border-t-purple-500", dot: "bg-purple-400", desc: "Waiting on parts" },
  { id: "repairing", title: "Repairing", color: "border-t-cyan-500", dot: "bg-cyan-400", desc: "Active repair work" },
  { id: "testing", title: "Testing / QA", color: "border-t-emerald-500", dot: "bg-emerald-400", desc: "Verifying fix" },
  { id: "ready", title: "Ready for Pickup", color: "border-t-green-500", dot: "bg-green-400", desc: "Complete, awaiting client" },
];

function BenchCard({ job, onDragStart }) {
  const daysIn = job.created_at ? Math.floor((Date.now() - new Date(job.created_at)) / 86400000) : 0;
  return (
    <div draggable onDragStart={e => onDragStart(e, job)}
      className="p-3 rounded-xl border border-border/70 bg-card hover:border-primary/35 hover:shadow-lg hover:shadow-primary/5 transition-all cursor-grab active:cursor-grabbing active:shadow-lg group"
      data-testid={`bench-card-${job.id}`}>
      <div className="flex items-center gap-1.5 mb-2">
        <GripVertical className="w-3 h-3 text-muted-foreground/30 opacity-0 group-hover:opacity-100 transition-opacity" />
        <span className="text-[10px] font-mono font-semibold text-primary/80">{job.job_number || "WS-?"}</span>
        <span className="ml-auto text-[9px] text-muted-foreground">{daysIn === 0 ? "Today" : `${daysIn}d in bench`}</span>
      </div>
      <p className="text-xs font-semibold leading-snug line-clamp-2 mb-2">{job.title || job.description || "Workshop repair"}</p>
      <div className="flex items-center justify-between text-[10px] border-t border-border/45 pt-2">
        <span className="text-muted-foreground truncate max-w-[55%]">{job.client_name || "Walk-in customer"}</span>
        {job.assigned_to_name && (
          <div className="flex items-center gap-1">
            <div className="w-4 h-4 rounded-full bg-primary/20 flex items-center justify-center"><span className="text-[8px] font-medium text-primary">{job.assigned_to_name.charAt(0)}</span></div>
            <span className="text-primary">{job.assigned_to_name.split(" ")[0]}</span>
          </div>
        )}
      </div>
      {job.device_name && <div className="flex items-center gap-1 mt-2 text-[10px] text-muted-foreground"><Monitor className="w-3 h-3 text-primary/70" />{job.device_name}</div>}
      {daysIn >= 3 && <div className="flex items-center gap-1 mt-2 text-[9px] text-red-300"><Timer className="w-3 h-3" />Attention: {daysIn} days in workshop</div>}
    </div>
  );
}

function BenchColumn({ col, jobs, onDrop, onDragStart, dragOver, setDragOver }) {
  return (
    <div className={`rounded-xl border border-t-4 ${col.color} bg-muted/[0.12] flex flex-col min-h-[55vh] transition-all ${dragOver === col.id ? "ring-2 ring-primary/30 bg-primary/5 scale-[1.01]" : ""}`}
      onDragOver={e => { e.preventDefault(); setDragOver(col.id); }} onDragLeave={() => setDragOver(null)}
      onDrop={e => { e.preventDefault(); setDragOver(null); onDrop(col.id); }}
      data-testid={`bench-col-${col.id}`}>
      <div className="p-3 border-b flex items-center justify-between flex-shrink-0 bg-background/40">
        <div className="flex items-center gap-2"><div className={`w-2 h-2 rounded-full ${col.dot} shadow-[0_0_8px_currentColor]`} /><h3 className="font-semibold text-xs">{col.title}</h3></div>
        <Badge variant="outline" className="text-[10px] font-mono rounded-md">{jobs.length}</Badge>
      </div>
      <p className="text-[9px] text-muted-foreground/65 px-3 pt-2 leading-snug">{col.desc}</p>
      <div className="p-2 space-y-2 flex-1 overflow-y-auto max-h-[55vh]">
        {jobs.length === 0 ? (
          <div className="flex items-center justify-center h-16 text-[10px] text-muted-foreground/40 border border-dashed rounded-lg">Drop here</div>
        ) : jobs.map(j => <BenchCard key={j.id} job={j} onDragStart={onDragStart} />)}
      </div>
    </div>
  );
}

export default function WorkshopBenchPage() {
  const { token } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [dragOver, setDragOver] = useState(null);
  const [dragging, setDragging] = useState(null);
  const [showNew, setShowNew] = useState(false);
  const [newForm, setNewForm] = useState({ title: "", description: "", client_name: "", device_name: "", assigned_to_name: "" });
  const [creating, setCreating] = useState(false);
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const fetchJobs = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/workshop/bench`, { headers });
      setJobs(res.data);
    } catch { toast.error("Failed to load workshop jobs"); }
    finally { setLoading(false); }
  }, [headers]);

  useEffect(() => { fetchJobs(); }, [fetchJobs]);

  const handleDragStart = (e, job) => { setDragging(job); e.dataTransfer.effectAllowed = "move"; };

  const handleDrop = async (newStage) => {
    if (!dragging || dragging.bench_stage === newStage) { setDragging(null); return; }
    const oldStage = dragging.bench_stage;
    setJobs(prev => prev.map(j => j.id === dragging.id ? { ...j, bench_stage: newStage } : j));
    try {
      await axios.put(`${API}/workshop/bench/move`, { job_id: dragging.id, stage: newStage }, { headers });
      toast.success(`Moved to ${newStage.replace("_", " ")}`);
    } catch { toast.error("Move failed"); fetchJobs(); }
    setDragging(null);
  };

  const createJob = async () => {
    if (!newForm.title) { toast.error("Title is required"); return; }
    setCreating(true);
    try {
      await axios.post(`${API}/workshop/bench`, newForm, { headers });
      toast.success("Workshop job created");
      setShowNew(false); setNewForm({ title: "", description: "", client_name: "", device_name: "", assigned_to_name: "" });
      fetchJobs();
    } catch { toast.error("Failed to create"); }
    finally { setCreating(false); }
  };

  const byStage = {};
  BENCH_COLUMNS.forEach(c => { byStage[c.id] = []; });
  jobs.filter(j => !search || j.title?.toLowerCase().includes(search.toLowerCase()) || j.client_name?.toLowerCase().includes(search.toLowerCase())).forEach(j => {
    const stage = j.bench_stage || "intake";
    if (byStage[stage]) byStage[stage].push(j); else byStage.intake.push(j);
  });

  const totalActive = jobs.filter(j => j.bench_stage !== "ready").length;
  const avgDays = jobs.length ? Math.round(jobs.reduce((s, j) => s + (j.created_at ? (Date.now() - new Date(j.created_at)) / 86400000 : 0), 0) / jobs.length) : 0;

  return (
    <div className="space-y-4" data-testid="workshop-bench-page">
      <div className="rounded-2xl border border-primary/20 bg-gradient-to-r from-primary/[0.12] via-primary/[0.035] to-transparent px-5 py-4 flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-xl bg-primary/15 border border-primary/25 flex items-center justify-center"><Wrench className="w-5 h-5 text-primary" /></div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">Workshop Bench</h1>
            <p className="text-muted-foreground text-xs mt-0.5">Drag cards across the repair flow to keep the floor current.</p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={fetchJobs} disabled={loading}><RefreshCw className={`w-4 h-4 mr-1 ${loading ? "animate-spin" : ""}`} />Refresh</Button>
          <Button size="sm" onClick={() => setShowNew(true)} data-testid="new-bench-job"><Plus className="w-4 h-4 mr-1" />Add bench job</Button>
        </div>
      </div>

      <MetricStrip columns={4}>
        <MetricTile label="On bench" value={jobs.length} accent="violet" icon={<Wrench className="w-2.5 h-2.5 text-violet-400" />} testid="bench-metric-total" />
        <MetricTile label="In progress" value={totalActive} accent="sky" icon={<Timer className="w-2.5 h-2.5 text-sky-400" />} testid="bench-metric-active" />
        <MetricTile label="Avg turnaround" value={`${avgDays}d`} accent="emerald" icon={<Clock className="w-2.5 h-2.5 text-emerald-400" />} testid="bench-metric-turnaround" />
        <MetricTile label="Needs attention" value={jobs.filter(j => j.created_at && (Date.now() - new Date(j.created_at)) >= 3 * 86400000).length} accent="rose" icon={<AlertTriangle className="w-2.5 h-2.5 text-rose-400" />} testid="bench-metric-attention" />
      </MetricStrip>

      <div className="flex items-center gap-3 rounded-xl border bg-card/60 p-3">
        <div className="relative flex-1 max-w-sm"><Search className="absolute left-3 top-2.5 w-4 h-4 text-muted-foreground" /><Input placeholder="Search job, customer or device..." value={search} onChange={e => setSearch(e.target.value)} className="pl-9 h-9" data-testid="bench-search" /></div>
        <span className="text-xs text-muted-foreground hidden sm:block">{search ? "Filtered repair board" : "Live repair board"}</span>
      </div>

      {loading ? (
        <div className="flex justify-center py-20"><Loader2 className="w-6 h-6 animate-spin text-muted-foreground" /></div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
          {BENCH_COLUMNS.map(col => (
            <BenchColumn key={col.id} col={col} jobs={byStage[col.id]} onDrop={handleDrop} onDragStart={handleDragStart} dragOver={dragOver} setDragOver={setDragOver} />
          ))}
        </div>
      )}

      {/* New Job Dialog */}
      <Dialog open={showNew} onOpenChange={setShowNew}>
        <DialogContent aria-describedby="new-bench-job-desc">
          <DialogHeader><DialogTitle>New Workshop Job</DialogTitle><DialogDescription id="new-bench-job-desc">Create a workshop repair/service job</DialogDescription></DialogHeader>
          <div className="space-y-3">
            <div><Label>Job Title *</Label><Input value={newForm.title} onChange={e => setNewForm({ ...newForm, title: e.target.value })} placeholder="e.g. Replace laptop screen" data-testid="bench-title" /></div>
            <div><Label>Description</Label><Textarea value={newForm.description} onChange={e => setNewForm({ ...newForm, description: e.target.value })} rows={2} placeholder="Details of the repair" /></div>
            <div className="grid grid-cols-2 gap-3">
              <div><Label>Client</Label><Input value={newForm.client_name} onChange={e => setNewForm({ ...newForm, client_name: e.target.value })} placeholder="Client name" /></div>
              <div><Label>Device</Label><Input value={newForm.device_name} onChange={e => setNewForm({ ...newForm, device_name: e.target.value })} placeholder="Device name/model" /></div>
            </div>
            <div><Label>Assign To</Label><Input value={newForm.assigned_to_name} onChange={e => setNewForm({ ...newForm, assigned_to_name: e.target.value })} placeholder="Technician name" /></div>
          </div>
          <DialogFooter><Button onClick={createJob} disabled={creating} data-testid="create-bench-btn">{creating ? <Loader2 className="w-4 h-4 mr-1 animate-spin" /> : <Plus className="w-4 h-4 mr-1" />}Create Job</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
